window.PAGES = window.PAGES || {};
window.PAGES["day5-theory"] = {"title": "OCI Networking, VCN, Compute & Storage \u2014 Day 5 | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 5 \u2014 ADDITIONAL WIDGET STYLES\n   (packet flow, CIDR/subnet designer, VCN builder canvas,\n   gateway comparison, security list/NSG editors, launch\n   wizard, cloud-init boot sequence, storage explorers,\n   ansible editor, topology map)\n   ============================================================ */\n\n/* --- packet flow / topology canvas --- */\n.topo-canvas-wrap{border:1px solid var(--border-strong); border-radius:var(--radius); background:var(--panel); padding:10px; overflow-x:auto;}\n\n/* --- subnet designer --- */\n.subnet-bar{height:46px; border-radius:8px; overflow:hidden; display:flex; border:1px solid var(--border-strong); margin:14px 0;}\n.subnet-seg{display:flex; align-items:center; justify-content:center; font-size:11px; color:#fff; font-weight:700; transition:.3s; cursor:pointer;}\n.subnet-legend{display:flex; flex-wrap:wrap; gap:10px; font-size:12px; margin-top:8px;}\n.subnet-legend span.sw{width:10px; height:10px; display:inline-block; border-radius:3px; margin-right:5px;}\n.subnet-list{margin-top:14px;}\n.subnet-row{display:flex; justify-content:space-between; align-items:center; padding:10px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:6px; font-size:13px;}\n\n/* --- IP planner --- */\n.ipplan-grid{display:flex; flex-direction:column; gap:8px;}\n.ipplan-row{display:flex; gap:8px; align-items:center; flex-wrap:wrap;}\n.ipplan-row input{width:150px;}\n.ipplan-status{font-size:11px; padding:3px 10px; border-radius:20px;}\n.ipplan-status.ok{background:var(--green-dim); color:var(--green);}\n.ipplan-status.overlap{background:var(--red-dim); color:var(--red-bright);}\n\n/* --- routing table --- */\n.route-table-ui{width:100%; font-size:12.5px; border-collapse:collapse; margin:10px 0;}\n.route-table-ui th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.route-table-ui td{padding:8px; border-bottom:1px solid var(--border); font-family:var(--font-mono); color:var(--text-2);}\n\n/* --- gateway comparison --- */\n.gw-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:12px;}\n.gw-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; text-align:center; cursor:pointer; transition:.2s;}\n.gw-card:hover, .gw-card.active{border-color:var(--red); background:var(--red-dim);}\n.gw-card .gw-ic{font-size:22px; margin-bottom:6px;}\n\n/* --- VCN builder canvas --- */\n.vcnb-layout{display:grid; grid-template-columns:260px 1fr; gap:16px;}\n@media (max-width:800px){.vcnb-layout{grid-template-columns:1fr;}}\n.vcnb-controls{display:flex; flex-direction:column; gap:10px;}\n.vcnb-canvas{min-height:360px; border:1px dashed var(--border-strong); border-radius:var(--radius); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.vcnb-vcn-box{border:2px solid var(--red); border-radius:10px; padding:14px; min-height:280px;}\n.vcnb-vcn-title{font-family:var(--font-mono); font-size:12px; color:var(--red-bright); margin-bottom:10px;}\n.vcnb-subnet-box{border:1px solid var(--border-strong); border-radius:8px; padding:10px; margin-bottom:10px; background:var(--panel);}\n.vcnb-subnet-box.public{border-left:3px solid var(--green);}\n.vcnb-subnet-box.private{border-left:3px solid var(--blue);}\n.vcnb-gw-row{display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;}\n.vcnb-gw-chip{font-size:11px; padding:4px 10px; border-radius:20px; background:var(--panel-2); border:1px solid var(--border);}\n.vcnb-validation{margin-top:12px; padding:10px 14px; border-radius:8px; font-size:12.5px; display:none;}\n.vcnb-validation.ok{display:block; background:var(--green-dim); color:var(--green);}\n.vcnb-validation.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n\n/* --- two-tier architecture --- */\n.arch2-diagram{display:flex; flex-direction:column; align-items:center; gap:6px; position:relative;}\n.arch2-tier{width:100%; max-width:520px; border:1px solid var(--border-strong); border-radius:10px; padding:14px; text-align:center; font-size:12.5px; background:var(--panel);}\n.arch2-tier.internet{border-color:var(--blue);}\n.arch2-tier.public-tier{border-color:var(--green);}\n.arch2-tier.private-tier{border-color:var(--amber);}\n.arch2-tier.db-tier{border-color:var(--red-bright);}\n.arch2-arrow{color:var(--text-3); font-size:16px;}\n\n/* --- security list / NSG editor --- */\n.rule-table{width:100%; font-size:12px; border-collapse:collapse; margin-top:10px;}\n.rule-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px;}\n.rule-table td{padding:6px; border-bottom:1px solid var(--border);}\n.rule-table select, .rule-table input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:5px; padding:4px 6px; font-size:11.5px; width:100%;}\n.rule-dir{font-size:10px; padding:2px 8px; border-radius:20px;}\n.rule-dir.ingress{background:var(--blue-dim); color:var(--blue);}\n.rule-dir.egress{background:var(--amber-dim); color:var(--amber);}\n\n/* --- launch wizard --- */\n.lw-shape-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:10px;}\n.lw-shape-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; cursor:pointer; font-size:12px; transition:.2s;}\n.lw-shape-card.selected{border-color:var(--red); background:var(--red-dim);}\n.lw-progress{display:flex; align-items:center; gap:8px; margin-bottom:6px;}\n.lw-boot-log{background:#0a0b0d; border-radius:8px; padding:14px; font-family:var(--font-mono); font-size:12px; color:#c9f7d8; min-height:120px; white-space:pre-wrap; margin-top:14px;}\n\n/* --- metadata explorer --- */\n.meta-tree{font-size:12.5px;}\n\n/* --- storage --- */\n.storage-compare-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:12px;}\n.storage-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; text-align:center; cursor:pointer; transition:.2s;}\n.storage-card:hover, .storage-card.active{border-color:var(--red);}\n.bucket-obj-row{display:flex; justify-content:space-between; align-items:center; padding:8px 12px; border-bottom:1px solid var(--border); font-size:12.5px;}\n.tier-slider-row{display:flex; gap:6px; margin:10px 0;}\n.tier-chip{flex:1; text-align:center; padding:10px; border-radius:8px; border:1px solid var(--border); font-size:11.5px; cursor:pointer; transition:.2s;}\n.tier-chip.active{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.vol-card{display:flex; justify-content:space-between; align-items:center; padding:10px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:8px; font-size:13px;}\n\n/* --- ansible editor --- */\n.yaml-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9d1d9; line-height:1.7;}\n.yaml-editor textarea{width:100%; min-height:200px; background:transparent; border:none; outline:none; color:#c9d1d9; font-family:var(--font-mono); font-size:12.5px; resize:vertical; line-height:1.7;}\n\n/* --- lab checklist --- */\n.lab-item{display:flex; align-items:flex-start; gap:12px; padding:14px; border:1px solid var(--border); border-radius:var(--radius-sm); margin-bottom:8px;}\n.lab-item.done{border-color:var(--green); background:var(--green-dim);}\n.lab-check{width:22px; height:22px; border-radius:6px; border:1px solid var(--border-strong); flex-shrink:0; display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:12px; margin-top:2px;}\n.lab-item.done .lab-check{background:var(--green); border-color:var(--green); color:#fff;}\n.lab-title{font-weight:700; font-size:13.5px;}\n.lab-desc{font-size:12.5px; color:var(--text-2); margin-top:2px;}\n\n/* --- topology map --- */\n.topology-svg{width:100%; height:auto;}\n.topo-node{cursor:pointer;}\n.topo-node:hover rect, .topo-node:hover circle{filter:brightness(1.3);}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Networking, VCN, Compute &amp; Storage \u00b7 Day 5</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search VCN, compute, storage topics\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Quiz score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1 \u00b7 Networking Deep Dive</div>\n      <a class=\"nav-link\" href=\"#sec-networking\"><span class=\"num\">01</span>Networking Fundamentals</a>\n      <a class=\"nav-link\" href=\"#sec-cidr\"><span class=\"num\">02</span>CIDR Planning</a>\n      <a class=\"nav-link\" href=\"#sec-subnetdesigner\"><span class=\"num\">03</span>Subnet Designer</a>\n      <a class=\"nav-link\" href=\"#sec-ipplanner\"><span class=\"num\">04</span>IP Address Planner</a>\n      <a class=\"nav-link\" href=\"#sec-routing\"><span class=\"num\">05</span>Routing &amp; Route Tables</a>\n      <a class=\"nav-link\" href=\"#sec-gateways\"><span class=\"num\">06</span>Gateways</a>\n      <a class=\"nav-link\" href=\"#sec-pubpriv\"><span class=\"num\">07</span>Public vs Private Subnets</a>\n      <a class=\"nav-link\" href=\"#sec-seclists\"><span class=\"num\">08</span>Security Lists</a>\n      <a class=\"nav-link\" href=\"#sec-nsg\"><span class=\"num\">09</span>NSGs &amp; Comparison</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 2 \u00b7 VCN Architecture</div>\n      <a class=\"nav-link\" href=\"#sec-vcnarch\"><span class=\"num\">10</span>VCN Architecture Concepts</a>\n      <a class=\"nav-link\" href=\"#sec-vcnbuilder\"><span class=\"num\">11</span>OCI VCN Builder</a>\n      <a class=\"nav-link\" href=\"#sec-twotier\"><span class=\"num\">12</span>Two-Tier Architecture</a>\n      <a class=\"nav-link\" href=\"#sec-vcnpeering\"><span class=\"num\">13</span>VCN Peering</a>\n      <a class=\"nav-link\" href=\"#sec-nettrouble\"><span class=\"num\">14</span>Outbound Troubleshooting</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3 \u00b7 Compute</div>\n      <a class=\"nav-link\" href=\"#sec-computearch\"><span class=\"num\">15</span>Compute Architecture &amp; Shapes</a>\n      <a class=\"nav-link\" href=\"#sec-launchwizard\"><span class=\"num\">16</span>Instance Launch Wizard</a>\n      <a class=\"nav-link\" href=\"#sec-cloudinit\"><span class=\"num\">17</span>Cloud-init &amp; Boot Process</a>\n      <a class=\"nav-link\" href=\"#sec-sshmeta\"><span class=\"num\">18</span>SSH &amp; Instance Metadata</a>\n      <a class=\"nav-link\" href=\"#sec-provisiontrouble\"><span class=\"num\">19</span>Provisioning Troubleshooting</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 4 \u00b7 Storage</div>\n      <a class=\"nav-link\" href=\"#sec-storageoverview\"><span class=\"num\">20</span>Storage Overview</a>\n      <a class=\"nav-link\" href=\"#sec-objectstorage\"><span class=\"num\">21</span>Object Storage</a>\n      <a class=\"nav-link\" href=\"#sec-blockstorage\"><span class=\"num\">22</span>Block Storage</a>\n      <a class=\"nav-link\" href=\"#sec-filestorage\"><span class=\"num\">23</span>File Storage</a>\n      <a class=\"nav-link\" href=\"#sec-storagedesign\"><span class=\"num\">24</span>Storage Design &amp; Cost</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 5 \u00b7 Config Management</div>\n      <a class=\"nav-link\" href=\"#sec-confmgmt\"><span class=\"num\">25</span>Ansible &amp; Terraform vs Ansible</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 6 \u00b7 Hands-On Lab</div>\n      <a class=\"nav-link\" href=\"#sec-console5\"><span class=\"num\">26</span>Console Simulator &amp; Topology</a>\n      <a class=\"nav-link\" href=\"#sec-cli5\"><span class=\"num\">27</span>CLI Terminal</a>\n      <a class=\"nav-link\" href=\"#sec-labs\"><span class=\"num\">28</span>Architecture Labs</a>\n      <a class=\"nav-link\" href=\"#sec-troubleshoot5\"><span class=\"num\">29</span>Troubleshooting Lab</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Wrap-Up</div>\n      <a class=\"nav-link\" href=\"#sec-cheatsheet5\"><span class=\"num\">30</span>Cheat Sheets</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards5\"><span class=\"num\">31</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-quiz5\"><span class=\"num\">32</span>Certification Quiz</a>\n      <a class=\"nav-link\" href=\"#sec-cert5\"><span class=\"num\">33</span>Certificate Preview</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Networking &amp; Infrastructure Track</span>\n      <h1>Day 5: Design it,<br>deploy it, <span class=\"accent\">run it.</span></h1>\n      <p class=\"lede\">CIDR planning, VCN architecture, gateways, compute launch, cloud-init, storage, and configuration management \u2014 build a real network end-to-end without an OCI account.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>33</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">20</b><span>Certification MCQs</span></div>\n        <div class=\"hstat\"><b>12</b><span>Live simulators</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-networking\" class=\"btn btn-primary\">Start learning \u2192</a>\n        <a href=\"#sec-quiz5\" class=\"btn btn-ghost\">Jump to certification quiz</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 NETWORKING FUNDAMENTALS -->\n<section class=\"chapter reveal\" id=\"sec-networking\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>Networking Fundamentals</h2>\n  <p class=\"dek\">Every cloud network is built from the same primitives you'd find in a physical data center.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>LAN</h4><p>A local network under one administrative domain \u2014 your VCN behaves like a private LAN.</p></div>\n    <div class=\"card\"><h4>WAN</h4><p>Networks spanning locations, connected over long-distance links \u2014 the internet is the largest WAN.</p></div>\n    <div class=\"card\"><h4>Packet Switching</h4><p>Data is broken into packets, each routed independently and reassembled at the destination.</p></div>\n    <div class=\"card\"><h4>Switching vs Routing</h4><p>Switching moves frames within a network by MAC address; routing moves packets between networks by IP address.</p></div>\n  </div>\n  <h3>Network devices</h3>\n  <div class=\"panel\">\n    <div class=\"topo-canvas-wrap\">\n      <div class=\"packet-path\" id=\"net-packet-path\" style=\"height:90px;\">\n        <div class=\"line\"></div>\n        <div class=\"node\" style=\"left:0%;\">\ud83d\udcbb Client</div>\n        <div class=\"node\" style=\"left:25%;\">\ud83d\udd00 Switch</div>\n        <div class=\"node\" style=\"left:50%;\">\ud83d\udce1 Router</div>\n        <div class=\"node\" style=\"left:75%;\">\ud83e\uddf1 Firewall</div>\n        <div class=\"node\" style=\"left:92%;\">\ud83d\udda5 Server</div>\n        <div class=\"packet-dot\" id=\"net-packet-dot\" style=\"left:0%;\"></div>\n      </div>\n    </div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"net-packet-play\">\u25b6 Send packet through the path</button></div>\n    <p class=\"small center mt-lg\" id=\"net-packet-msg\">Watch a packet cross a switch, router, and firewall on its way to a server.</p>\n  </div>\n</section>\n\n<!-- 02 CIDR PLANNING -->\n<section class=\"chapter reveal\" id=\"sec-cidr\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>CIDR Planning</h2>\n  <p class=\"dek\">Every VCN and subnet is defined by a CIDR block. Change the prefix and watch every derived value update.</p>\n  <div class=\"panel\">\n    <div class=\"ip-octets\">\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"10\" id=\"c-o1\"><span>.</span>\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"0\" id=\"c-o2\"><span>.</span>\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"0\" id=\"c-o3\"><span>.</span>\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"0\" id=\"c-o4\">\n      <span>/</span><input type=\"number\" min=\"1\" max=\"32\" value=\"16\" id=\"c-prefix\" style=\"width:50px;\">\n    </div>\n    <input type=\"range\" min=\"8\" max=\"30\" value=\"16\" id=\"c-prefix-slider\" class=\"cidr-slider\">\n    <div class=\"ip-result-grid\" id=\"c-results\"></div>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>OCI VCN CIDR blocks must fall between /16 and /30. Plan the VCN CIDR large enough up front \u2014 you can add secondary CIDR blocks later, but redesigning subnets after the fact is disruptive.</div></div>\n</section>\n\n<!-- 03 SUBNET DESIGNER -->\n<section class=\"chapter reveal\" id=\"sec-subnetdesigner\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>Subnet Designer</h2>\n  <p class=\"dek\">Split a 10.0.0.0/16 VCN into 5 purpose-built subnets and see the address space allocated visually.</p>\n  <div class=\"panel\">\n    <div class=\"subnet-bar\" id=\"subnet-bar\"></div>\n    <div class=\"subnet-legend\" id=\"subnet-legend\"></div>\n    <div class=\"subnet-list\" id=\"subnet-list\"></div>\n  </div>\n</section>\n\n<!-- 04 IP ADDRESS PLANNER -->\n<section class=\"chapter reveal\" id=\"sec-ipplanner\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>IP Address Planner</h2>\n  <p class=\"dek\">Assign CIDR blocks to subnets \u2014 the validator flags overlaps in real time.</p>\n  <div class=\"panel\">\n    <div class=\"ipplan-grid\" id=\"ipplan-rows\"></div>\n    <button class=\"chip-btn active mt-lg\" id=\"ipplan-add\">\uff0b Add subnet</button>\n  </div>\n</section>\n\n<!-- 05 ROUTING & ROUTE TABLES -->\n<section class=\"chapter reveal\" id=\"sec-routing\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>Routing &amp; Route Tables</h2>\n  <p class=\"dek\">A route table decides where traffic goes next, using longest-prefix-match \u2014 the most specific matching rule wins.</p>\n  <div class=\"panel\">\n    <table class=\"route-table-ui\" id=\"route-table\"><thead><tr><th>Destination CIDR</th><th>Target</th></tr></thead><tbody></tbody></table>\n    <div style=\"display:flex; gap:8px; margin-top:10px; flex-wrap:wrap;\">\n      <input class=\"mini-input\" id=\"rt-dest\" placeholder=\"destination CIDR, e.g. 172.16.0.0/16\" style=\"flex:1;\">\n      <input class=\"mini-input\" id=\"rt-target\" placeholder=\"target, e.g. DRG\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"rt-add\">Add rule</button>\n    </div>\n    <div style=\"display:flex; gap:8px; margin-top:14px;\">\n      <input class=\"mini-input\" id=\"rt-test-ip\" placeholder=\"test destination IP, e.g. 172.16.5.10\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"rt-test\">Which route wins?</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"rt-result\"></p>\n  </div>\n</section>\n\n<!-- 06 GATEWAYS -->\n<section class=\"chapter reveal\" id=\"sec-gateways\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>Gateways</h2>\n  <p class=\"dek\">Click a gateway to see what traffic it handles and animate the flow.</p>\n  <div class=\"gw-grid\" id=\"gw-grid\">\n    <div class=\"gw-card\" data-gw=\"igw\"><div class=\"gw-ic\">\ud83c\udf10</div>Internet Gateway</div>\n    <div class=\"gw-card\" data-gw=\"nat\"><div class=\"gw-ic\">\ud83d\udd01</div>NAT Gateway</div>\n    <div class=\"gw-card\" data-gw=\"sgw\"><div class=\"gw-ic\">\ud83d\udd12</div>Service Gateway</div>\n    <div class=\"gw-card\" data-gw=\"drg\"><div class=\"gw-ic\">\ud83c\udfdb</div>Dynamic Routing Gateway</div>\n    <div class=\"gw-card\" data-gw=\"lpg\"><div class=\"gw-ic\">\ud83d\udd17</div>Local Peering Gateway</div>\n  </div>\n  <div class=\"panel mt-lg\" id=\"gw-detail-panel\">\n    <p class=\"small\" id=\"gw-detail-text\">Click a gateway above.</p>\n    <div class=\"packet-path\" id=\"gw-packet-path\" style=\"height:90px; display:none;\">\n      <div class=\"line\"></div>\n      <div class=\"node\" style=\"left:0%;\" id=\"gw-node-a\">Subnet</div>\n      <div class=\"node\" style=\"left:85%;\" id=\"gw-node-b\">Destination</div>\n      <div class=\"packet-dot\" id=\"gw-packet-dot\" style=\"left:0%;\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- 07 PUBLIC VS PRIVATE SUBNETS -->\n<section class=\"chapter reveal\" id=\"sec-pubpriv\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>Public vs Private Subnets</h2>\n  <p class=\"dek\">Move the VM between subnets and see how its connectivity changes.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\"><button class=\"chip-btn active\" data-subnetplace=\"public\">Place VM in Public Subnet</button><button class=\"chip-btn\" data-subnetplace=\"private\">Place VM in Private Subnet</button></div>\n    <div class=\"grid grid-3 mt-lg\">\n      <div class=\"card\"><h4>\ud83c\udf10 Internet (inbound)</h4><p id=\"conn-internet-in\"></p></div>\n      <div class=\"card\"><h4>\ud83c\udf10 Internet (outbound)</h4><p id=\"conn-internet-out\"></p></div>\n      <div class=\"card\"><h4>\ud83d\udd12 OCI Services</h4><p id=\"conn-oci\"></p></div>\n    </div>\n  </div>\n</section>\n\n<!-- 08 SECURITY LISTS -->\n<section class=\"chapter reveal\" id=\"sec-seclists\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>Security Lists</h2>\n  <p class=\"dek\">Stateful, subnet-level firewall rules. Build a rule set and test traffic against it.</p>\n  <div class=\"panel\">\n    <table class=\"rule-table\" id=\"sl-table\"><thead><tr><th>Direction</th><th>Source/Dest</th><th>Protocol</th><th>Port</th><th></th></tr></thead><tbody></tbody></table>\n    <button class=\"chip-btn active\" id=\"sl-add\">\uff0b Add rule</button>\n    <div style=\"display:flex; gap:8px; margin-top:14px; flex-wrap:wrap;\">\n      <input class=\"mini-input\" id=\"sl-test-port\" placeholder=\"test inbound port, e.g. 22\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"sl-test\">Test</button>\n    </div>\n    <p class=\"small mt-lg\" id=\"sl-test-result\"></p>\n  </div>\n</section>\n\n<!-- 09 NSGs & COMPARISON -->\n<section class=\"chapter reveal\" id=\"sec-nsg\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">Networking Deep Dive</span></div>\n  <h2>NSGs &amp; Security Lists vs NSGs</h2>\n  <p class=\"dek\">Network Security Groups apply rules to specific VNICs, not entire subnets \u2014 much finer-grained.</p>\n  <table class=\"decision-matrix\">\n    <tr><th></th><th>Security Lists</th><th>NSGs</th></tr>\n    <tr><td>Scope</td><td>Entire subnet</td><td>Individual VNICs</td></tr>\n    <tr><td>Best for</td><td>Broad, subnet-wide baseline rules</td><td>Per-tier or per-app fine-grained rules</td></tr>\n    <tr><td>Can combine?</td><td colspan=\"2\">Yes \u2014 both apply simultaneously; traffic must pass both</td></tr>\n  </table>\n  <h3>Scenario selector</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"dtree\">\n      <div class=\"dt-q\">You need to allow port 443 only for your specific \"web-tier\" instances, not the whole subnet. What do you use?</div>\n      <div class=\"dt-opts\"><button class=\"chip-btn\" data-nsgq=\"sl\">Security List</button><button class=\"chip-btn\" data-nsgq=\"nsg\">NSG</button></div>\n      <div class=\"dt-result\" id=\"nsgq-result\"></div>\n    </div>\n  </div>\n</section>\n<!-- 10 VCN ARCHITECTURE CONCEPTS -->\n<section class=\"chapter reveal\" id=\"sec-vcnarch\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">VCN Architecture</span></div>\n  <h2>VCN Architecture Concepts</h2>\n  <p class=\"dek\">A Virtual Cloud Network is your private, software-defined network inside OCI.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>VCN</h4><p>A private network with its own CIDR block, isolated from other tenancies.</p></div>\n    <div class=\"card\"><h4>Subnet</h4><p>A subdivision of the VCN's CIDR, regional or AD-specific, public or private.</p></div>\n    <div class=\"card\"><h4>VNIC</h4><p>A virtual network interface attached to a compute instance, carrying its private (and optionally public) IP.</p></div>\n    <div class=\"card\"><h4>DHCP Options / DNS Labels</h4><p>Control internal DNS resolution and hostname assignment within the VCN.</p></div>\n  </div>\n</section>\n\n<!-- 11 OCI VCN BUILDER -->\n<section class=\"chapter reveal\" id=\"sec-vcnbuilder\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">VCN Architecture</span></div>\n  <h2>OCI VCN Builder</h2>\n  <p class=\"dek\">Build a VCN step by step. Add subnets and gateways and watch the diagram \u2014 and validation \u2014 update live.</p>\n  <div class=\"vcnb-layout\">\n    <div class=\"vcnb-controls\">\n      <div class=\"field-row\"><label>VCN CIDR</label><input class=\"mini-input\" id=\"vb-vcn-cidr\" value=\"10.0.0.0/16\" style=\"width:100%;\"></div>\n      <div class=\"field-row\"><label>Add subnet</label>\n        <input class=\"mini-input\" id=\"vb-subnet-name\" placeholder=\"subnet name\" style=\"width:100%; margin-bottom:6px;\">\n        <input class=\"mini-input\" id=\"vb-subnet-cidr\" placeholder=\"CIDR e.g. 10.0.1.0/24\" style=\"width:100%; margin-bottom:6px;\">\n        <select class=\"mini-input\" id=\"vb-subnet-type\" style=\"width:100%;\"><option value=\"public\">Public</option><option value=\"private\">Private</option></select>\n      </div>\n      <button class=\"chip-btn active\" id=\"vb-add-subnet\">\uff0b Add subnet</button>\n      <div class=\"field-row mt-lg\"><label>Attach gateway</label>\n        <div style=\"display:flex; gap:6px; flex-wrap:wrap;\">\n          <button class=\"chip-btn\" data-vbgw=\"IGW\">+ IGW</button>\n          <button class=\"chip-btn\" data-vbgw=\"NAT\">+ NAT</button>\n          <button class=\"chip-btn\" data-vbgw=\"SGW\">+ SGW</button>\n        </div>\n      </div>\n    </div>\n    <div class=\"vcnb-canvas\">\n      <div class=\"vcnb-vcn-box\">\n        <div class=\"vcnb-vcn-title\" id=\"vb-vcn-title\">VCN \u2014 10.0.0.0/16</div>\n        <div id=\"vb-subnets\"></div>\n        <div class=\"vcnb-gw-row\" id=\"vb-gateways\"></div>\n      </div>\n      <div class=\"vcnb-validation\" id=\"vb-validation\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- 12 TWO-TIER ARCHITECTURE -->\n<section class=\"chapter reveal\" id=\"sec-twotier\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">VCN Architecture</span></div>\n  <h2>Public/Private Two-Tier Architecture</h2>\n  <p class=\"dek\">The canonical OCI pattern: internet-facing load balancer, app tier in a public subnet, database tier fully private.</p>\n  <div class=\"panel\">\n    <div class=\"arch2-diagram\">\n      <div class=\"arch2-tier internet\" id=\"a2-internet\">\ud83c\udf10 Internet</div>\n      <div class=\"arch2-arrow\">\u2193</div>\n      <div class=\"arch2-tier public-tier\" id=\"a2-lb\">\u2696\ufe0f Load Balancer (Public Subnet)</div>\n      <div class=\"arch2-arrow\">\u2193</div>\n      <div class=\"arch2-tier public-tier\" id=\"a2-app\">\ud83d\udda5 Application Tier (Public Subnet)</div>\n      <div class=\"arch2-arrow\">\u2193</div>\n      <div class=\"arch2-tier private-tier\" id=\"a2-db\">\ud83d\uddc4 Database Tier (Private Subnet)</div>\n    </div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"a2-play\">\u25b6 Animate a user request</button></div>\n    <p class=\"small center mt-lg\" id=\"a2-msg\">Click play to trace a request from the internet down to the database \u2014 and the response back.</p>\n  </div>\n</section>\n\n<!-- 13 VCN PEERING -->\n<section class=\"chapter reveal\" id=\"sec-vcnpeering\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">VCN Architecture</span></div>\n  <h2>VCN Peering</h2>\n  <p class=\"dek\">Two VCNs can talk to each other privately without traversing the internet.</p>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>\ud83d\udd17 Local Peering (LPG)</h4><p>Connects two VCNs in the <strong>same region</strong>, via a Local Peering Gateway on each side.</p></div>\n    <div class=\"card\"><h4>\ud83c\udf0d Remote Peering (via DRG)</h4><p>Connects two VCNs in <strong>different regions</strong>, using a Dynamic Routing Gateway on each side.</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <div class=\"packet-path\" id=\"peer-path\" style=\"height:90px;\">\n      <div class=\"line\"></div>\n      <div class=\"node\" style=\"left:5%;\">VCN-A</div>\n      <div class=\"node\" style=\"left:45%;\">LPG/DRG</div>\n      <div class=\"node\" style=\"left:88%;\">VCN-B</div>\n      <div class=\"packet-dot\" id=\"peer-dot\" style=\"left:5%;\"></div>\n    </div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"peer-play\">\u25b6 Animate cross-VCN traffic</button></div>\n  </div>\n</section>\n\n<!-- 14 OUTBOUND TROUBLESHOOTING -->\n<section class=\"chapter reveal\" id=\"sec-nettrouble\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">VCN Architecture</span></div>\n  <h2>Common Mistake &amp; Outbound Troubleshooting</h2>\n  <p class=\"dek\">A private-subnet instance can't reach the internet. Use the packet analyzer to find the missing piece.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"net-analyze\">\ud83d\udd0d Run packet analyzer</button>\n    <div class=\"flow-steps mt-lg\" id=\"net-analyze-steps\"></div>\n    <p class=\"small mt-lg\" id=\"net-analyze-result\"></p>\n  </div>\n</section>\n<!-- 15 COMPUTE ARCHITECTURE & SHAPES -->\n<section class=\"chapter reveal\" id=\"sec-computearch\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Compute</span></div>\n  <h2>Compute Architecture &amp; Shapes</h2>\n  <p class=\"dek\">OCI compute ranges from shared VMs to bare metal dedicated purely to you.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>Virtual Machine</h4><p>Shares physical hardware with other tenants via the hypervisor. Fast to provision, flexible shapes.</p></div>\n    <div class=\"card\"><h4>Bare Metal</h4><p>An entire physical server dedicated to you \u2014 no hypervisor overhead, full hardware access.</p></div>\n    <div class=\"card\"><h4>Dedicated Host</h4><p>A physical server reserved for your VMs only \u2014 isolation without going fully bare metal.</p></div>\n    <div class=\"card\"><h4>GPU / HPC Shapes</h4><p>Specialized shapes for ML training or tightly-coupled HPC workloads with cluster networking.</p></div>\n  </div>\n  <h3>Flex shape selector</h3>\n  <div class=\"panel\">\n    <div class=\"field-row\"><label>OCPUs</label><input type=\"range\" id=\"shape-ocpu\" min=\"1\" max=\"32\" value=\"2\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">OCPUs: <strong id=\"shape-ocpu-val\">2</strong></p></div>\n    <div class=\"field-row\"><label>Memory (GB)</label><input type=\"range\" id=\"shape-mem\" min=\"4\" max=\"512\" value=\"16\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">Memory: <strong id=\"shape-mem-val\">16 GB</strong></p></div>\n    <p class=\"small mt-lg\">Shape: <span class=\"mono\" id=\"shape-preview\" style=\"color:var(--blue);\">VM.Standard.E4.Flex \u2014 2 OCPU / 16 GB</span></p>\n  </div>\n</section>\n\n<!-- 16 INSTANCE LAUNCH WIZARD -->\n<section class=\"chapter reveal\" id=\"sec-launchwizard\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Compute</span></div>\n  <h2>Instance Launch Wizard</h2>\n  <p class=\"dek\">The same flow as the real OCI Console launch page.</p>\n  <div class=\"panel\">\n    <div class=\"field-row\"><label>Image</label><select class=\"mini-input\" id=\"lw-image\" style=\"width:100%;\"><option>Oracle Linux 9</option><option>Ubuntu 24.04</option><option>Windows Server 2022</option><option>Custom Image</option></select></div>\n    <div class=\"lw-shape-grid mt-lg\" id=\"lw-shapes\">\n      <div class=\"lw-shape-card selected\" data-shape=\"VM.Standard.E4.Flex\">VM.Standard.E4.Flex</div>\n      <div class=\"lw-shape-card\" data-shape=\"VM.Standard.A1.Flex\">VM.Standard.A1.Flex (Ampere)</div>\n      <div class=\"lw-shape-card\" data-shape=\"BM.GPU.A10.1\">BM.GPU.A10.1</div>\n      <div class=\"lw-shape-card\" data-shape=\"VM.DenseIO.E4.Flex\">VM.DenseIO.E4.Flex</div>\n    </div>\n    <div class=\"field-row mt-lg\"><label>VCN / Subnet</label><select class=\"mini-input\" id=\"lw-subnet\" style=\"width:100%;\"><option>prod-vcn / public-web-subnet</option><option>prod-vcn / private-app-subnet</option></select></div>\n    <div class=\"field-row\"><label>SSH public key</label><textarea class=\"mini-input\" id=\"lw-sshkey\" style=\"width:100%; min-height:60px; font-family:var(--font-mono);\" placeholder=\"ssh-rsa AAAA...\">ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQC7x...</textarea></div>\n    <div class=\"field-row\"><label>Boot volume size (GB)</label><input type=\"range\" id=\"lw-bootvol\" min=\"50\" max=\"500\" value=\"50\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">Size: <strong id=\"lw-bootvol-val\">50 GB</strong></p></div>\n    <button class=\"chip-btn active mt-lg\" id=\"lw-launch\">Launch Instance</button>\n    <div class=\"lw-boot-log\" id=\"lw-log\" style=\"display:none;\"></div>\n  </div>\n</section>\n<!-- 17 CLOUD-INIT & BOOT PROCESS -->\n<section class=\"chapter reveal\" id=\"sec-cloudinit\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Compute</span></div>\n  <h2>Cloud-init &amp; Boot Process</h2>\n  <p class=\"dek\">cloud-init runs on first boot to configure the instance from your launch-time script.</p>\n  <div class=\"policy-editor\"><textarea id=\"ci-editor\" spellcheck=\"false\" style=\"min-height:170px;\">#cloud-config\npackages:\n  - nginx\n  - git\n\nusers:\n  - name: deploy\n    groups: sudo\n    shell: /bin/bash\n\nruncmd:\n  - systemctl enable nginx\n  - systemctl start nginx\n  - echo \"Provisioned by cloud-init\" &gt; /var/www/html/index.html</textarea></div>\n  <button class=\"chip-btn active mt-lg\" id=\"ci-run\">Boot instance with this config</button>\n  <div class=\"lw-boot-log\" id=\"ci-boot-log\"></div>\n  <h3>Boot sequence</h3>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"boot-seq\"></div>\n  </div>\n</section>\n\n<!-- 18 SSH & INSTANCE METADATA -->\n<section class=\"chapter reveal\" id=\"sec-sshmeta\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Compute</span></div>\n  <h2>SSH &amp; Instance Metadata</h2>\n  <div class=\"panel\">\n    <p class=\"mono\" style=\"color:var(--blue);\">ssh -i ~/.ssh/id_rsa opc@140.238.10.5</p>\n    <button class=\"chip-btn active mt-lg\" id=\"ssh-connect-btn\">Connect</button>\n    <div class=\"lw-boot-log\" id=\"ssh-connect-log\"></div>\n  </div>\n  <h3>Instance metadata explorer</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"cost-filters\">\n      <button class=\"chip-btn active\" data-meta=\"/latest/meta-data/\">GET /latest/meta-data/</button>\n      <button class=\"chip-btn\" data-meta=\"/latest/meta-data/instance-id\">/instance-id</button>\n      <button class=\"chip-btn\" data-meta=\"/latest/meta-data/vnics\">/vnics</button>\n      <button class=\"chip-btn\" data-meta=\"/latest/user-data\">/user-data</button>\n    </div>\n    <div class=\"lw-boot-log\" id=\"meta-out\" style=\"margin-top:14px;\"></div>\n  </div>\n</section>\n\n<!-- 19 PROVISIONING TROUBLESHOOTING -->\n<section class=\"chapter reveal\" id=\"sec-provisiontrouble\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Compute</span></div>\n  <h2>Provisioning Troubleshooting</h2>\n  <p class=\"dek\">Pick a failure symptom, diagnose it.</p>\n  <div class=\"cost-filters\" id=\"prov-case-btns\">\n    <button class=\"chip-btn active\" data-provcase=\"stuck\">Instance stuck provisioning</button>\n    <button class=\"chip-btn\" data-provcase=\"cloudinitfail\">Cloud-init failure</button>\n    <button class=\"chip-btn\" data-provcase=\"bootvol\">Boot volume issue</button>\n    <button class=\"chip-btn\" data-provcase=\"wrongimage\">Wrong image selected</button>\n  </div>\n  <div class=\"panel\" id=\"prov-panel\"></div>\n</section>\n<!-- 20 STORAGE OVERVIEW -->\n<section class=\"chapter reveal\" id=\"sec-storageoverview\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">20</span><span class=\"track\">Storage</span></div>\n  <h2>Storage Overview</h2>\n  <p class=\"dek\">Four storage types, each solving a different access pattern.</p>\n  <div class=\"storage-compare-grid\">\n    <div class=\"card\"><h4>\ud83d\udce6 Object Storage</h4><p>HTTP-accessible, unlimited scale, for unstructured data \u2014 backups, media, logs.</p></div>\n    <div class=\"card\"><h4>\ud83d\udcbd Block Storage</h4><p>Raw attached volumes for compute instances \u2014 boot volumes and data volumes.</p></div>\n    <div class=\"card\"><h4>\ud83d\udcc1 File Storage</h4><p>Shared NFS filesystem, mountable by multiple instances at once.</p></div>\n    <div class=\"card\"><h4>\ud83d\uddc4 Archive Storage</h4><p>Lowest cost, retrieval takes hours \u2014 for long-term compliance retention.</p></div>\n  </div>\n</section>\n\n<!-- 21 OBJECT STORAGE -->\n<section class=\"chapter reveal\" id=\"sec-objectstorage\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">21</span><span class=\"track\">Storage</span></div>\n  <h2>Object Storage</h2>\n  <p class=\"dek\">Buckets hold objects. Try creating a bucket and uploading objects below.</p>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/object-storage</span></div>\n    <div class=\"console-main\" style=\"padding:16px;\">\n      <div class=\"console-toolbar\">\n        <input class=\"mini-input\" id=\"bkt-name\" placeholder=\"bucket name\" style=\"flex:1;\">\n        <select class=\"mini-input\" id=\"bkt-tier\"><option>Standard</option><option>Infrequent Access</option><option>Archive</option></select>\n        <button class=\"chip-btn active\" id=\"bkt-create\">Create Bucket</button>\n      </div>\n      <div id=\"bkt-list\"></div>\n    </div>\n  </div>\n  <div class=\"grid grid-3 mt-lg\">\n    <div class=\"card\"><h4>Versioning</h4><p>Keeps prior versions of an object when overwritten \u2014 protects against accidental deletes.</p></div>\n    <div class=\"card\"><h4>Lifecycle Policies</h4><p>Automatically transitions or deletes objects by age \u2014 e.g. move to Archive after 90 days.</p></div>\n    <div class=\"card\"><h4>Pre-Authenticated Requests</h4><p>Time-limited, credential-free URLs for one specific object or bucket.</p></div>\n  </div>\n</section>\n\n<!-- 22 BLOCK STORAGE -->\n<section class=\"chapter reveal\" id=\"sec-blockstorage\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">22</span><span class=\"track\">Storage</span></div>\n  <h2>Block Storage</h2>\n  <p class=\"dek\">Attach, back up, clone, and resize volumes.</p>\n  <div class=\"panel\" id=\"block-vol-panel\">\n    <button class=\"chip-btn active\" id=\"bv-create\">\uff0b Create 100GB Volume</button>\n    <div id=\"bv-list\" class=\"mt-lg\"></div>\n  </div>\n</section>\n\n<!-- 23 FILE STORAGE -->\n<section class=\"chapter reveal\" id=\"sec-filestorage\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">23</span><span class=\"track\">Storage</span></div>\n  <h2>File Storage (NFS)</h2>\n  <p class=\"dek\">A File System exposes exports through a Mount Target that multiple instances share.</p>\n  <div class=\"panel\">\n    <p class=\"mono\" style=\"color:var(--blue);\">sudo mount -t nfs 10.0.1.8:/shared-data /mnt/shared</p>\n    <button class=\"chip-btn active mt-lg\" id=\"nfs-mount\">Mount on instance</button>\n    <p class=\"small mt-lg\" id=\"nfs-result\"></p>\n  </div>\n  <div class=\"grid grid-3 mt-lg\">\n    <div class=\"card\"><h4>File System</h4><p>The logical NFS filesystem storing your data.</p></div>\n    <div class=\"card\"><h4>Mount Target</h4><p>The network endpoint (private IP) instances connect to.</p></div>\n    <div class=\"card\"><h4>Export</h4><p>Defines which path is shared and with what access options/security.</p></div>\n  </div>\n</section>\n\n<!-- 24 STORAGE DESIGN & COST OPTIMIZATION -->\n<section class=\"chapter reveal\" id=\"sec-storagedesign\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">24</span><span class=\"track\">Storage</span></div>\n  <h2>Storage Design &amp; Cost Optimization</h2>\n  <p class=\"dek\">Pick a workload and get a storage recommendation.</p>\n  <div class=\"cost-filters\" id=\"storage-workload-btns\">\n    <button class=\"chip-btn active\" data-sw=\"db\">Database data files</button>\n    <button class=\"chip-btn\" data-sw=\"backup\">Nightly backups, kept 1 year</button>\n    <button class=\"chip-btn\" data-sw=\"shared\">Shared config across 10 web servers</button>\n    <button class=\"chip-btn\" data-sw=\"media\">User-uploaded photos/videos</button>\n  </div>\n  <p class=\"mt-lg\" id=\"storage-reco\" style=\"color:var(--text-2);\"></p>\n\n  <h3>Storage tier cost simulator</h3>\n  <div class=\"panel mt-lg\">\n    <p class=\"small\">1 TB of data, accessed rarely. Move it between tiers and watch monthly cost change.</p>\n    <div class=\"tier-slider-row\" id=\"tier-chips\">\n      <div class=\"tier-chip active\" data-tier=\"standard\">Standard</div>\n      <div class=\"tier-chip\" data-tier=\"ia\">Infrequent Access</div>\n      <div class=\"tier-chip\" data-tier=\"archive\">Archive</div>\n    </div>\n    <p class=\"small mt-lg\">Estimated monthly cost: <strong id=\"tier-cost\" style=\"color:var(--red-bright);\">$25.60</strong></p>\n  </div>\n</section>\n\n<!-- 25 CONFIGURATION MANAGEMENT -->\n<section class=\"chapter reveal\" id=\"sec-confmgmt\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">25</span><span class=\"track\">Configuration Management</span></div>\n  <h2>Ansible &amp; Terraform vs Ansible</h2>\n  <p class=\"dek\">Terraform provisions infrastructure; Ansible configures what runs on top of it. Write a playbook and \"run\" it.</p>\n  <div class=\"yaml-editor\"><textarea id=\"ansible-editor\" spellcheck=\"false\">---\n- name: Configure web servers\n  hosts: webservers\n  become: true\n  tasks:\n    - name: Install nginx\n      package:\n        name: nginx\n        state: present\n\n    - name: Start nginx\n      service:\n        name: nginx\n        state: started\n        enabled: true\n\n    - name: Deploy app\n      copy:\n        src: index.html\n        dest: /var/www/html/index.html</textarea></div>\n  <button class=\"chip-btn active mt-lg\" id=\"ansible-run\">\u25b6 Run playbook</button>\n  <div class=\"lw-boot-log\" id=\"ansible-out\"></div>\n\n  <h3>Terraform vs Ansible</h3>\n  <table class=\"decision-matrix mt-lg\">\n    <tr><th></th><th>Terraform</th><th>Ansible</th></tr>\n    <tr><td>Purpose</td><td>Provision infrastructure (VCN, compute, storage)</td><td>Configure software on existing infrastructure</td></tr>\n    <tr><td>Model</td><td>Declarative, stateful (tracks a state file)</td><td>Procedural task list, agentless via SSH</td></tr>\n    <tr><td>Typical use with OCI</td><td>Create the VCN and launch the instance</td><td>Install and configure nginx on that instance</td></tr>\n  </table>\n</section>\n<!-- 26 CONSOLE SIMULATOR & TOPOLOGY -->\n<section class=\"chapter reveal\" id=\"sec-console5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">26</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>OCI Console Simulator &amp; Network Topology</h2>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/networking</span></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\">\n        <div class=\"active\" data-panel5=\"vcns5\">\ud83c\udf10 VCNs</div>\n        <div data-panel5=\"instances5\">\ud83d\udda5 Instances</div>\n        <div data-panel5=\"volumes5\">\ud83d\udcbd Volumes</div>\n        <div data-panel5=\"buckets5\">\ud83d\udce6 Buckets</div>\n      </div>\n      <div class=\"console-main\">\n        <div class=\"console-panel5\" id=\"panel5-vcns5\">\n          <table class=\"console-table\"><thead><tr><th>VCN</th><th>CIDR</th><th>Subnets</th><th></th></tr></thead>\n          <tbody><tr><td>prod-vcn</td><td>10.0.0.0/16</td><td>3</td><td><span class=\"status-pill active\">Available</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel5\" id=\"panel5-instances5\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Name</th><th>Shape</th><th>State</th></tr></thead>\n          <tbody><tr><td>web-vm-01</td><td>VM.Standard.E4.Flex</td><td><span class=\"status-pill active\">Running</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel5\" id=\"panel5-volumes5\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Volume</th><th>Size</th><th>State</th></tr></thead>\n          <tbody><tr><td>web-vm-01-boot</td><td>50 GB</td><td><span class=\"status-pill active\">Attached</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel5\" id=\"panel5-buckets5\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Bucket</th><th>Tier</th></tr></thead>\n          <tbody><tr><td>app-backups</td><td>Standard</td></tr></tbody></table>\n        </div>\n      </div>\n    </div>\n  </div>\n  <h3>Network topology view</h3>\n  <div class=\"panel mt-lg\">\n    <svg viewBox=\"0 0 640 240\" class=\"topology-svg\" id=\"topology-svg\">\n      <rect x=\"20\" y=\"90\" width=\"600\" height=\"130\" rx=\"10\" fill=\"none\" stroke=\"var(--border-strong)\" stroke-dasharray=\"4 3\"/>\n      <text x=\"30\" y=\"82\" font-size=\"11\" fill=\"var(--text-3)\" font-family=\"monospace\">prod-vcn 10.0.0.0/16</text>\n      <g class=\"topo-node\" data-t=\"igw\"><circle cx=\"60\" cy=\"120\" r=\"18\" fill=\"var(--red-dim)\" stroke=\"var(--red-bright)\"/><text x=\"60\" y=\"125\" text-anchor=\"middle\" font-size=\"14\">\ud83c\udf10</text><text x=\"60\" y=\"150\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-3)\">IGW</text></g>\n      <g class=\"topo-node\" data-t=\"public-subnet\"><rect x=\"120\" y=\"105\" width=\"130\" height=\"60\" rx=\"8\" fill=\"var(--green-dim)\" stroke=\"var(--green)\"/><text x=\"185\" y=\"130\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--green)\">Public Subnet</text><text x=\"185\" y=\"148\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-3)\">10.0.1.0/24</text></g>\n      <g class=\"topo-node\" data-t=\"nat\"><circle cx=\"300\" cy=\"120\" r=\"18\" fill=\"var(--blue-dim)\" stroke=\"var(--blue)\"/><text x=\"300\" y=\"125\" text-anchor=\"middle\" font-size=\"14\">\ud83d\udd01</text><text x=\"300\" y=\"150\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-3)\">NAT</text></g>\n      <g class=\"topo-node\" data-t=\"private-subnet\"><rect x=\"360\" y=\"105\" width=\"130\" height=\"60\" rx=\"8\" fill=\"var(--blue-dim)\" stroke=\"var(--blue)\"/><text x=\"425\" y=\"130\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--blue)\">Private Subnet</text><text x=\"425\" y=\"148\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-3)\">10.0.2.0/24</text></g>\n      <g class=\"topo-node\" data-t=\"sgw\"><circle cx=\"560\" cy=\"120\" r=\"18\" fill=\"var(--amber-dim)\" stroke=\"var(--amber)\"/><text x=\"560\" y=\"125\" text-anchor=\"middle\" font-size=\"14\">\ud83d\udd12</text><text x=\"560\" y=\"150\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--text-3)\">SGW</text></g>\n      <line x1=\"78\" y1=\"120\" x2=\"120\" y2=\"120\" stroke=\"var(--border-strong)\"/>\n      <line x1=\"250\" y1=\"120\" x2=\"282\" y2=\"120\" stroke=\"var(--border-strong)\"/>\n      <line x1=\"318\" y1=\"120\" x2=\"360\" y2=\"120\" stroke=\"var(--border-strong)\"/>\n      <line x1=\"490\" y1=\"120\" x2=\"542\" y2=\"120\" stroke=\"var(--border-strong)\"/>\n    </svg>\n    <p class=\"small center\" id=\"topo-detail\">Click a node above for details.</p>\n  </div>\n</section>\n\n<!-- 27 CLI TERMINAL -->\n<section class=\"chapter reveal\" id=\"sec-cli5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">27</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>CLI Terminal</h2>\n  <div class=\"terminal\">\n    <div class=\"terminal-tb\">oci-cli \u2014 networking &amp; compute \u2014 simulator</div>\n    <div id=\"term-out5\"></div>\n    <div class=\"term-input-row\"><span>$</span><input id=\"term-input5\" type=\"text\" placeholder=\"type: help\" autocomplete=\"off\"></div>\n  </div>\n  <p class=\"small mt-lg\">Try: <span class=\"mono\">help, oci network vcn create, oci network subnet create, oci network route-table create, oci network security-list list, oci compute instance launch, oci compute instance list, oci bv volume create, oci os bucket create, oci fs file-system create, clear</span></p>\n</section>\n\n<!-- 28 ARCHITECTURE LABS -->\n<section class=\"chapter reveal\" id=\"sec-labs\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">28</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Architecture Labs</h2>\n  <p class=\"dek\">Check off each lab as you complete the matching section above.</p>\n  <div id=\"labs-list\"></div>\n  <p class=\"small center mt-lg\" id=\"labs-progress\">0 / 12 labs complete</p>\n</section>\n\n<!-- 29 TROUBLESHOOTING LAB -->\n<section class=\"chapter reveal\" id=\"sec-troubleshoot5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">29</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Troubleshooting Lab</h2>\n  <div class=\"cost-filters\" id=\"ts5-case-btns\">\n    <button class=\"chip-btn active\" data-case5=\"sshfail\">SSH Failure</button>\n    <button class=\"chip-btn\" data-case5=\"nointernet\">No Internet</button>\n    <button class=\"chip-btn\" data-case5=\"wrongroute\">Wrong Route</button>\n    <button class=\"chip-btn\" data-case5=\"slblock\">Security List Block</button>\n    <button class=\"chip-btn\" data-case5=\"nsgblock\">NSG Block</button>\n    <button class=\"chip-btn\" data-case5=\"cifail\">Cloud-init Failure</button>\n    <button class=\"chip-btn\" data-case5=\"bvfail\">Boot Volume Failure</button>\n    <button class=\"chip-btn\" data-case5=\"ospermission\">Object Storage Permission</button>\n    <button class=\"chip-btn\" data-case5=\"mountfail\">Volume Mount Failure</button>\n  </div>\n  <div class=\"panel\" id=\"ts5-panel\"></div>\n</section>\n\n<!-- 30 CHEAT SHEETS -->\n<section class=\"chapter reveal\" id=\"sec-cheatsheet5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">30</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Cheat Sheets</h2>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>VCN &amp; CIDR</h4><ul style=\"margin-left:16px;\"><li>VCN CIDR: /16 to /30</li><li>/24 = 254 usable hosts</li><li>Route tables use longest-prefix-match</li></ul></div>\n    <div class=\"card\"><h4>Gateways</h4><ul style=\"margin-left:16px;\"><li>IGW = public inbound+outbound</li><li>NAT = private outbound only</li><li>SGW = private access to OCI services (no internet)</li></ul></div>\n    <div class=\"card\"><h4>Security</h4><ul style=\"margin-left:16px;\"><li>Security Lists = subnet-wide, stateful</li><li>NSGs = per-VNIC, finer-grained</li><li>Both apply simultaneously if both are attached</li></ul></div>\n    <div class=\"card\"><h4>Compute &amp; Storage</h4><ul style=\"margin-left:16px;\"><li>cloud-init runs once, on first boot</li><li>Object = HTTP; Block = attached; File = shared NFS</li><li>Terraform provisions, Ansible configures</li></ul></div>\n  </div>\n  <table class=\"cmp mt-lg\"><tr><th>CLI Reference</th></tr>\n    <tr><td class=\"mono\">oci network vcn create</td></tr><tr><td class=\"mono\">oci network subnet create</td></tr>\n    <tr><td class=\"mono\">oci network route-table create</td></tr><tr><td class=\"mono\">oci compute instance launch</td></tr>\n    <tr><td class=\"mono\">oci bv volume create</td></tr><tr><td class=\"mono\">oci os bucket create</td></tr>\n    <tr><td class=\"mono\">oci fs file-system create</td></tr></table>\n</section>\n\n<!-- 31 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">31</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Flash Cards</h2>\n  <div class=\"flash-wrap\" id=\"flash-wrap5\"></div>\n</section>\n\n<!-- 32 QUIZ -->\n<section class=\"chapter reveal\" id=\"sec-quiz5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">32</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Certification Readiness Quiz</h2>\n  <div id=\"quiz-wrap5\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score5\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 33 CERTIFICATE -->\n<section class=\"chapter reveal\" id=\"sec-cert5\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">33</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Completion &amp; Certificate Preview</h2>\n  <div class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle5\"><span id=\"badge-pct5\">0%</span></div>\n    <h3 id=\"badge-title5\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub5\">Complete every section and the quiz to preview your certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 5: Networking, VCN, Compute &amp; Storage</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display5\">0/20</span> \u00b7 Date: <span id=\"cert-date-display5\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Networking, VCN, Compute &amp; Storage \u2014 Day 5 \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n", "js": "\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0, labsDone:new Set() };\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initNetPacket(); initCidrCalc(); initSubnetDesigner(); initIpPlanner(); initRouting(); initGateways();\n  initPubPriv(); initSecLists(); initNsgCompare();\n  initVcnBuilder(); initTwoTier(); initVcnPeering(); initNetTrouble();\n  initShapeSelector(); initLaunchWizard(); initCloudInit(); initSshMeta(); initProvisionTrouble();\n  initObjectStorage(); initBlockStorage(); initFileStorage(); initStorageDesign();\n  initAnsible();\n  initConsoleSim5(); initTopology(); initTerminal5(); initLabs(); initTroubleshoot5();\n  initFlashcards5(); initQuiz5(); updateBadge5();\n});\nfunction initParticles(){\n  const c=document.getElementById('particles'); const ctx=c.getContext('2d'); let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N=Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){ ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar=document.getElementById('progress-bar'); const heroProgress=document.getElementById('hero-progress');\n  window.addEventListener('scroll', ()=>{\n    const scrollTop=window.scrollY; const docH=document.documentElement.scrollHeight-window.innerHeight;\n    const pct=docH>0?(scrollTop/docH)*100:0;\n    bar.style.width=pct+'%'; if(heroProgress) heroProgress.textContent=Math.round(pct)+'%';\n    window.__lastScrollPct5=pct; updateBadge5(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections=document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect=sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=>a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title=sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML=matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n;\n\n/* ---------- networking packet flow ---------- */\nfunction initNetPacket(){\n  const btn = document.getElementById('net-packet-play'); if(!btn) return;\n  const dot = document.getElementById('net-packet-dot'); const msg = document.getElementById('net-packet-msg');\n  const stops = [0,25,50,75,92]; const labels = ['Leaving client','Switched locally','Routed onward','Firewall inspects','Delivered to server'];\n  btn.addEventListener('click', ()=>{\n    let i=0;\n    function step(){ dot.style.left=stops[i]+'%'; msg.textContent=labels[i]; i++; if(i<stops.length) setTimeout(step,600); else msg.textContent='\u2713 Packet delivered.'; }\n    step();\n  });\n}\n\n/* ---------- CIDR calculator (reused pattern) ---------- */\nfunction initCidrCalc(){\n  const slider = document.getElementById('c-prefix-slider'); if(!slider) return;\n  const octets = ['c-o1','c-o2','c-o3','c-o4'].map(id=>document.getElementById(id));\n  const prefixInput = document.getElementById('c-prefix');\n  function ipToInt(a,b,c,d){ return ((a<<24)>>>0)+(b<<16)+(c<<8)+d; }\n  function intToIp(n){ return [(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255].join('.'); }\n  function calc(){\n    const [a,b,c,d] = octets.map(o=>Math.max(0,Math.min(255,parseInt(o.value)||0)));\n    let prefix = Math.max(1,Math.min(32,parseInt(prefixInput.value)||16));\n    slider.value=prefix; prefixInput.value=prefix;\n    const ipInt = ipToInt(a,b,c,d);\n    const maskInt = prefix===0?0:(0xFFFFFFFF<<(32-prefix))>>>0;\n    const network = (ipInt & maskInt)>>>0;\n    const broadcast = (network | (~maskInt>>>0))>>>0;\n    const total = Math.pow(2,32-prefix); const usable = Math.max(0,total-2);\n    document.getElementById('c-results').innerHTML = `\n      <div class=\"ip-result-item\">Network Address<b>${intToIp(network)}</b></div>\n      <div class=\"ip-result-item\">Broadcast Address<b>${intToIp(broadcast)}</b></div>\n      <div class=\"ip-result-item\">Subnet Mask<b>${intToIp(maskInt)}</b></div>\n      <div class=\"ip-result-item\">Total Addresses<b>${total}</b></div>\n      <div class=\"ip-result-item\">Usable Hosts (OCI)<b>${Math.max(0,usable-3)}</b></div>\n      <div class=\"ip-result-item\">First / Last Usable<b>${usable>0?intToIp(network+1)+' \u2013 '+intToIp(broadcast-1):'\u2014'}</b></div>`;\n  }\n  octets.forEach(o=>o.addEventListener('input',calc));\n  prefixInput.addEventListener('input',calc);\n  slider.addEventListener('input', ()=>{ prefixInput.value=slider.value; calc(); });\n  calc();\n}\n\n/* ---------- subnet designer ---------- */\nfunction initSubnetDesigner(){\n  const bar = document.getElementById('subnet-bar'); if(!bar) return;\n  const subnets = [\n    {name:'Public', cidr:'10.0.0.0/24', pct:20, color:'#3ec28f'},\n    {name:'Private-App', cidr:'10.0.1.0/24', pct:20, color:'#4f8cff'},\n    {name:'Database', cidr:'10.0.2.0/24', pct:20, color:'#c74634'},\n    {name:'Management', cidr:'10.0.3.0/26', pct:15, color:'#e8a33d'},\n    {name:'Backup', cidr:'10.0.4.0/24', pct:25, color:'#9096a2'},\n  ];\n  bar.innerHTML = subnets.map(s=>`<div class=\"subnet-seg\" style=\"width:${s.pct}%; background:${s.color};\" data-name=\"${s.name}\">${s.name}</div>`).join('');\n  document.getElementById('subnet-legend').innerHTML = subnets.map(s=>`<span><span class=\"sw\" style=\"background:${s.color}\"></span>${s.name}: ${s.cidr}</span>`).join('');\n  document.getElementById('subnet-list').innerHTML = subnets.map(s=>`<div class=\"subnet-row\"><span>${s.name}</span><span class=\"mono\" style=\"color:var(--blue);\">${s.cidr}</span></div>`).join('');\n}\n\n/* ---------- IP address planner ---------- */\nfunction initIpPlanner(){\n  const wrap = document.getElementById('ipplan-rows'); if(!wrap) return;\n  let rows = [{name:'public-web', cidr:'10.0.0.0/24'}, {name:'private-app', cidr:'10.0.1.0/24'}];\n  function cidrToRange(cidr){\n    const [ip,pfx] = cidr.split('/'); const p = parseInt(pfx);\n    if(!ip || isNaN(p)) return null;\n    const parts = ip.split('.').map(Number);\n    if(parts.length!==4 || parts.some(isNaN)) return null;\n    const ipInt = (parts[0]<<24)+(parts[1]<<16)+(parts[2]<<8)+parts[3];\n    const mask = p===0?0:(0xFFFFFFFF<<(32-p))>>>0;\n    const net = (ipInt & mask)>>>0;\n    const bcast = (net | (~mask>>>0))>>>0;\n    return [net,bcast];\n  }\n  function render(){\n    wrap.innerHTML = rows.map((r,i)=>`\n      <div class=\"ipplan-row\">\n        <input class=\"mini-input\" data-i=\"${i}\" data-f=\"name\" value=\"${r.name}\" placeholder=\"subnet name\">\n        <input class=\"mini-input\" data-i=\"${i}\" data-f=\"cidr\" value=\"${r.cidr}\" placeholder=\"CIDR\">\n        <span class=\"ipplan-status\" id=\"ipplan-status-${i}\"></span>\n      </div>`).join('');\n    validate();\n  }\n  function validate(){\n    const ranges = rows.map(r=>cidrToRange(r.cidr));\n    rows.forEach((r,i)=>{\n      const el = document.getElementById('ipplan-status-'+i); if(!el) return;\n      const rr = ranges[i];\n      if(!rr){ el.className='ipplan-status overlap'; el.textContent='invalid CIDR'; return; }\n      let overlap=false;\n      ranges.forEach((other,j)=>{ if(i!==j && other && !(rr[1]<other[0] || rr[0]>other[1])) overlap=true; });\n      el.className = 'ipplan-status ' + (overlap?'overlap':'ok');\n      el.textContent = overlap ? 'overlaps!' : 'ok';\n    });\n  }\n  wrap.addEventListener('input', e=>{\n    const i = e.target.dataset.i, f = e.target.dataset.f; if(i===undefined) return;\n    rows[i][f] = e.target.value; validate();\n  });\n  document.getElementById('ipplan-add').addEventListener('click', ()=>{\n    rows.push({name:'subnet-'+(rows.length+1), cidr:'10.0.'+rows.length+'.0/24'}); render();\n  });\n  render();\n}\n\n/* ---------- routing ---------- */\nfunction initRouting(){\n  const tbody = document.querySelector('#route-table tbody'); if(!tbody) return;\n  let rules = [['10.0.0.0/16','local'],['0.0.0.0/0','Internet Gateway']];\n  function render(){ tbody.innerHTML = rules.map(([d,t])=>`<tr><td>${d}</td><td>${t}</td></tr>`).join(''); }\n  document.getElementById('rt-add').addEventListener('click', ()=>{\n    const d = document.getElementById('rt-dest').value.trim(); const t = document.getElementById('rt-target').value.trim();\n    if(!d||!t) return;\n    rules.push([d,t]); render();\n    document.getElementById('rt-dest').value=''; document.getElementById('rt-target').value='';\n  });\n  function prefixLen(cidr){ return parseInt(cidr.split('/')[1]); }\n  function ipInRange(ip, cidr){\n    const [netIp,pfx] = cidr.split('/'); const p = parseInt(pfx);\n    const toInt = s=> s.split('.').reduce((a,o)=>(a<<8)+parseInt(o),0)>>>0;\n    const mask = p===0?0:(0xFFFFFFFF<<(32-p))>>>0;\n    return (toInt(ip)&mask) === (toInt(netIp)&mask);\n  }\n  document.getElementById('rt-test').addEventListener('click', ()=>{\n    const ip = document.getElementById('rt-test-ip').value.trim();\n    const result = document.getElementById('rt-result');\n    if(!ip){ result.textContent='Enter a test IP.'; return; }\n    const matches = rules.filter(([d])=> ipInRange(ip,d)).sort((a,b)=> prefixLen(b[0])-prefixLen(a[0]));\n    if(matches.length===0){ result.textContent = `No matching route for ${ip}.`; result.style.color='var(--red-bright)'; }\n    else { result.innerHTML = `\u2713 Longest-prefix-match winner: <span class=\"mono\" style=\"color:var(--blue);\">${matches[0][0]} \u2192 ${matches[0][1]}</span>`; result.style.color='var(--green)'; }\n  });\n  render();\n}\n\n/* ---------- gateways ---------- */\nfunction initGateways(){\n  const cards = document.querySelectorAll('#gw-grid .gw-card'); if(!cards.length) return;\n  const detailText = document.getElementById('gw-detail-text');\n  const path = document.getElementById('gw-packet-path'); const dot = document.getElementById('gw-packet-dot');\n  const nodeA = document.getElementById('gw-node-a'); const nodeB = document.getElementById('gw-node-b');\n  const info = {\n    igw: {text:'Internet Gateway: allows both inbound and outbound internet traffic for resources with a public IP.', a:'Public Subnet', b:'Internet'},\n    nat: {text:'NAT Gateway: allows outbound-only internet access for private subnets \u2014 no inbound connections initiated from outside.', a:'Private Subnet', b:'Internet (outbound only)'},\n    sgw: {text:'Service Gateway: private access to OCI public services (Object Storage, etc.) without traversing the internet.', a:'Private Subnet', b:'OCI Services'},\n    drg: {text:'Dynamic Routing Gateway: the hub for VPN, FastConnect, remote VCN peering, and on-premises connectivity.', a:'VCN', b:'On-Premises / Remote VCN'},\n    lpg: {text:'Local Peering Gateway: connects two VCNs in the same region directly, privately.', a:'VCN-A', b:'VCN-B (same region)'}\n  };\n  cards.forEach(c=>{\n    c.addEventListener('click', ()=>{\n      cards.forEach(x=>x.classList.remove('active')); c.classList.add('active');\n      const d = info[c.dataset.gw];\n      detailText.textContent = d.text;\n      path.style.display='block'; nodeA.textContent=d.a; nodeB.textContent=d.b; dot.style.left='0%';\n      setTimeout(()=> dot.style.left='85%', 200);\n    });\n  });\n}\n\n/* ---------- public vs private subnets ---------- */\nfunction initPubPriv(){\n  const btns = document.querySelectorAll('[data-subnetplace]'); if(!btns.length) return;\n  function render(place){\n    if(place==='public'){\n      document.getElementById('conn-internet-in').textContent = '\u2713 Reachable if a security rule allows it (has a public IP via IGW).';\n      document.getElementById('conn-internet-out').textContent = '\u2713 Direct outbound via Internet Gateway.';\n      document.getElementById('conn-oci').textContent = '\u2713 Reachable (via IGW or optionally SGW).';\n    } else {\n      document.getElementById('conn-internet-in').textContent = '\u2717 Not reachable \u2014 no public IP, no route from the internet.';\n      document.getElementById('conn-internet-out').textContent = '\u2713 Reachable only if a NAT Gateway is configured.';\n      document.getElementById('conn-oci').textContent = '\u2713 Reachable via Service Gateway, entirely privately.';\n    }\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.subnetplace); }));\n  render('public');\n}\n\n/* ---------- security lists ---------- */\nfunction initSecLists(){\n  const tbody = document.querySelector('#sl-table tbody'); if(!tbody) return;\n  let rules = [{dir:'ingress', src:'0.0.0.0/0', proto:'TCP', port:'22'}, {dir:'egress', src:'0.0.0.0/0', proto:'All', port:'All'}];\n  function render(){\n    tbody.innerHTML = rules.map(r=>`<tr><td><span class=\"rule-dir ${r.dir}\">${r.dir}</span></td><td>${r.src}</td><td>${r.proto}</td><td>${r.port}</td></tr>`).join('');\n  }\n  document.getElementById('sl-add').addEventListener('click', ()=>{\n    rules.push({dir:'ingress', src:'0.0.0.0/0', proto:'TCP', port:'443'}); render();\n  });\n  document.getElementById('sl-test').addEventListener('click', ()=>{\n    const port = document.getElementById('sl-test-port').value.trim();\n    const result = document.getElementById('sl-test-result');\n    const allowed = rules.some(r=> r.dir==='ingress' && (r.port==='All' || r.port===port));\n    result.textContent = allowed ? `\u2713 Inbound port ${port} is allowed by an existing rule.` : `\u2717 Inbound port ${port} is blocked \u2014 no matching ingress rule.`;\n    result.style.color = allowed ? 'var(--green)' : 'var(--red-bright)';\n  });\n  render();\n}\n\n/* ---------- NSG comparison scenario ---------- */\nfunction initNsgCompare(){\n  const btns = document.querySelectorAll('[data-nsgq]'); if(!btns.length) return;\n  const result = document.getElementById('nsgq-result');\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      if(b.dataset.nsgq==='nsg'){ result.style.display='block'; result.style.background='var(--green-dim)'; result.style.color='var(--green)'; result.style.borderColor='rgba(62,194,143,.35)'; result.textContent='\u2713 Correct \u2014 NSGs target specific VNICs, letting you scope the rule to just the web-tier instances without affecting the rest of the subnet.'; }\n      else { result.style.display='block'; result.style.background='var(--red-dim)'; result.style.color='var(--red-bright)'; result.style.borderColor='rgba(199,70,52,.35)'; result.textContent='\u2717 A Security List applies to the entire subnet \u2014 it can\\'t scope to only specific instances within it.'; }\n    });\n  });\n}\n\n;\n\n/* ---------- VCN Builder ---------- */\nfunction initVcnBuilder(){\n  const addBtn = document.getElementById('vb-add-subnet'); if(!addBtn) return;\n  let subnets = []; let gateways = [];\n  const title = document.getElementById('vb-vcn-title');\n  document.getElementById('vb-vcn-cidr').addEventListener('input', e=>{ title.textContent = 'VCN \u2014 '+e.target.value; validate(); });\n  function cidrRange(cidr){\n    const [ip,pfx] = cidr.split('/'); const p = parseInt(pfx);\n    if(!ip||isNaN(p)) return null;\n    const parts = ip.split('.').map(Number); if(parts.length!==4||parts.some(isNaN)) return null;\n    const ipInt=(parts[0]<<24)+(parts[1]<<16)+(parts[2]<<8)+parts[3];\n    const mask = p===0?0:(0xFFFFFFFF<<(32-p))>>>0;\n    const net=(ipInt&mask)>>>0; const bcast=(net|(~mask>>>0))>>>0;\n    return [net,bcast];\n  }\n  function renderSubnets(){\n    document.getElementById('vb-subnets').innerHTML = subnets.map(s=>`<div class=\"vcnb-subnet-box ${s.type}\"><strong>${s.name}</strong> \u2014 <span class=\"mono\">${s.cidr}</span> (${s.type})</div>`).join('') || '<p class=\"small\">No subnets yet.</p>';\n  }\n  function renderGw(){\n    document.getElementById('vb-gateways').innerHTML = gateways.map(g=>`<span class=\"vcnb-gw-chip\">${g}</span>`).join('') || '<span class=\"small\">No gateways attached.</span>';\n  }\n  function validate(){\n    const vcnRange = cidrRange(document.getElementById('vb-vcn-cidr').value.trim());\n    const val = document.getElementById('vb-validation');\n    if(!vcnRange){ val.className='vcnb-validation bad'; val.textContent='Invalid VCN CIDR.'; return; }\n    let problems = [];\n    const ranges = subnets.map(s=>({...s, range:cidrRange(s.cidr)}));\n    ranges.forEach(s=>{ if(!s.range) problems.push(`\"${s.name}\" has an invalid CIDR.`); else if(s.range[0]<vcnRange[0] || s.range[1]>vcnRange[1]) problems.push(`\"${s.name}\" (${s.cidr}) falls outside the VCN CIDR.`); });\n    ranges.forEach((s,i)=> ranges.forEach((o,j)=>{ if(i<j && s.range && o.range && !(s.range[1]<o.range[0]||s.range[0]>o.range[1])) problems.push(`\"${s.name}\" overlaps with \"${o.name}\".`); }));\n    if(subnets.some(s=>s.type==='public') && !gateways.includes('IGW')) problems.push('A public subnet exists but no Internet Gateway is attached.');\n    if(problems.length){ val.className='vcnb-validation bad'; val.innerHTML = '\u26a0 '+problems.join('<br>\u26a0 '); }\n    else { val.className='vcnb-validation ok'; val.textContent = '\u2713 Configuration looks valid.'; }\n  }\n  addBtn.addEventListener('click', ()=>{\n    const name = document.getElementById('vb-subnet-name').value.trim() || 'subnet-'+(subnets.length+1);\n    const cidr = document.getElementById('vb-subnet-cidr').value.trim();\n    const type = document.getElementById('vb-subnet-type').value;\n    if(!cidr) return;\n    subnets.push({name,cidr,type});\n    document.getElementById('vb-subnet-name').value=''; document.getElementById('vb-subnet-cidr').value='';\n    renderSubnets(); validate();\n  });\n  document.querySelectorAll('[data-vbgw]').forEach(b=>{\n    b.addEventListener('click', ()=>{ if(!gateways.includes(b.dataset.vbgw)) gateways.push(b.dataset.vbgw); renderGw(); validate(); });\n  });\n  renderSubnets(); renderGw(); validate();\n}\n\n/* ---------- two-tier architecture animation ---------- */\nfunction initTwoTier(){\n  const btn = document.getElementById('a2-play'); if(!btn) return;\n  const tiers = ['a2-internet','a2-lb','a2-app','a2-db'];\n  btn.addEventListener('click', ()=>{\n    tiers.forEach(id=> document.getElementById(id).style.boxShadow='none');\n    const msg = document.getElementById('a2-msg');\n    tiers.forEach((id,i)=> setTimeout(()=>{\n      document.getElementById(id).style.boxShadow='0 0 0 3px var(--red-dim)';\n      msg.textContent = i===0?'Request enters from the internet\u2026' : i===1?'Load Balancer distributes to app tier\u2026' : i===2?'App tier processes and queries the database\u2026' : 'Database responds \u2014 data flows back up the same path.';\n    }, i*600));\n  });\n}\n\n/* ---------- VCN peering ---------- */\nfunction initVcnPeering(){\n  const btn = document.getElementById('peer-play'); if(!btn) return;\n  const dot = document.getElementById('peer-dot');\n  btn.addEventListener('click', ()=>{ dot.style.left='5%'; setTimeout(()=> dot.style.left='45%', 100); setTimeout(()=> dot.style.left='88%', 700); });\n}\n\n/* ---------- outbound troubleshooting ---------- */\nfunction initNetTrouble(){\n  const btn = document.getElementById('net-analyze'); if(!btn) return;\n  const stepsWrap = document.getElementById('net-analyze-steps');\n  const checks = ['Check Route Table','Check Internet/NAT Gateway','Check Security List','Check NSG','Check DNS resolution'];\n  stepsWrap.innerHTML = checks.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  btn.addEventListener('click', ()=>{\n    const els = stepsWrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    const result = document.getElementById('net-analyze-result');\n    checks.forEach((s,i)=> setTimeout(()=>{\n      els[i].classList.add('lit');\n      if(i===1){ result.innerHTML = '\ud83d\udd0e Found it: the route table for this private subnet has <strong>no rule pointing to a NAT Gateway</strong> for 0.0.0.0/0.'; result.style.color='var(--amber)'; }\n      if(i===checks.length-1) setTimeout(()=>{ result.innerHTML += '<br>\u2713 Fix: add a route rule for 0.0.0.0/0 \u2192 NAT Gateway in this subnet\\'s route table.'; result.style.color='var(--green)'; }, 400);\n    }, i*450));\n  });\n}\n\n;\n\n/* ---------- shape selector ---------- */\nfunction initShapeSelector(){\n  const ocpu = document.getElementById('shape-ocpu'); if(!ocpu) return;\n  const mem = document.getElementById('shape-mem');\n  function render(){\n    document.getElementById('shape-ocpu-val').textContent = ocpu.value;\n    document.getElementById('shape-mem-val').textContent = mem.value+' GB';\n    document.getElementById('shape-preview').textContent = `VM.Standard.E4.Flex \u2014 ${ocpu.value} OCPU / ${mem.value} GB`;\n  }\n  ocpu.addEventListener('input', render); mem.addEventListener('input', render); render();\n}\n\n/* ---------- launch wizard ---------- */\nfunction initLaunchWizard(){\n  const cards = document.querySelectorAll('#lw-shapes .lw-shape-card'); if(!cards.length) return;\n  cards.forEach(c=> c.addEventListener('click', ()=>{ cards.forEach(x=>x.classList.remove('selected')); c.classList.add('selected'); }));\n  const bootvol = document.getElementById('lw-bootvol');\n  bootvol.addEventListener('input', ()=> document.getElementById('lw-bootvol-val').textContent = bootvol.value+' GB');\n  document.getElementById('lw-launch').addEventListener('click', ()=>{\n    const log = document.getElementById('lw-log'); log.style.display='block';\n    const shape = document.querySelector('#lw-shapes .selected').dataset.shape;\n    const image = document.getElementById('lw-image').value;\n    const steps = [\n      `Validating launch request\u2026`,\n      `Reserving shape: ${shape}`,\n      `Attaching image: ${image}`,\n      `Creating boot volume (${bootvol.value} GB)\u2026`,\n      `Attaching VNIC in ${document.getElementById('lw-subnet').value}`,\n      `Injecting SSH key\u2026`,\n      `Instance state: PROVISIONING`,\n      `Instance state: RUNNING`,\n      `\u2713 Instance launched successfully.`\n    ];\n    log.textContent = '';\n    steps.forEach((s,i)=> setTimeout(()=>{ log.textContent += s+'\\n'; log.scrollTop = log.scrollHeight;\n      if(i===steps.length-1) state.labsDone.add('launch');\n    }, i*450));\n  });\n}\n\n/* ---------- cloud-init & boot process ---------- */\nfunction initCloudInit(){\n  const runBtn = document.getElementById('ci-run'); if(!runBtn) return;\n  const bootSeq = document.getElementById('boot-seq');\n  const seqSteps = ['BIOS/UEFI','Bootloader','Kernel Init','cloud-init: network stage','cloud-init: config stage','cloud-init: final stage (runcmd)','SSH daemon ready','Application ready'];\n  bootSeq.innerHTML = seqSteps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  runBtn.addEventListener('click', ()=>{\n    const src = document.getElementById('ci-editor').value;\n    const log = document.getElementById('ci-boot-log');\n    const els = bootSeq.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    log.textContent = '';\n    const packages = (src.match(/packages:([\\s\\S]*?)(\\n\\S|\\nusers:|\\nruncmd:|$)/)||[])[1] || '';\n    const pkgList = packages.split('\\n').map(l=>l.trim().replace(/^-\\s*/,'')).filter(Boolean);\n    const runcmds = (src.match(/runcmd:([\\s\\S]*)/)||[])[1] || '';\n    const cmdList = runcmds.split('\\n').map(l=>l.trim().replace(/^-\\s*/,'')).filter(Boolean);\n    let lines = ['[cloud-init] starting...'];\n    pkgList.forEach(p=> lines.push(`[cloud-init] installing package: ${p}`));\n    cmdList.forEach(c=> lines.push(`[cloud-init] runcmd: ${c}`));\n    lines.push('[cloud-init] finished. up 8.42 seconds');\n    seqSteps.forEach((s,i)=> setTimeout(()=> els[i].classList.add('lit'), i*350));\n    lines.forEach((l,i)=> setTimeout(()=>{ log.textContent += l+'\\n'; log.scrollTop=log.scrollHeight; }, i*250+300));\n  });\n}\n\n/* ---------- SSH & metadata ---------- */\nfunction initSshMeta(){\n  const btn = document.getElementById('ssh-connect-btn'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const log = document.getElementById('ssh-connect-log');\n    log.textContent = 'The authenticity of host \\'140.238.10.5\\' can\\'t be established.\\nED25519 key fingerprint is SHA256:AbCdEf...\\nAre you sure you want to continue connecting (yes/no)? yes\\nWarning: Permanently added to known_hosts.\\n[opc@web-vm-01 ~]$ \u2713 connected';\n  });\n  const metaBtns = document.querySelectorAll('[data-meta]');\n  const metaOut = document.getElementById('meta-out');\n  const responses = {\n    '/latest/meta-data/': 'ami-id\\ninstance-id\\ninstance-type\\nlocal-ipv4\\npublic-ipv4\\nvnics\\nhostname',\n    '/latest/meta-data/instance-id': 'ocid1.instance.oc1.iad.anuwcljt...',\n    '/latest/meta-data/vnics': '[{\"vnicId\":\"ocid1.vnic.oc1..aaa\",\"privateIp\":\"10.0.1.15\",\"subnetCidrBlock\":\"10.0.1.0/24\"}]',\n    '/latest/user-data': '(base64-encoded cloud-init script provided at launch)'\n  };\n  metaBtns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      metaBtns.forEach(x=>x.classList.remove('active')); b.classList.add('active');\n      metaOut.textContent = `$ curl -H \"Authorization: Bearer Oracle\" http://169.254.169.254${b.dataset.meta}\\n${responses[b.dataset.meta]}`;\n    });\n  });\n}\n\n/* ---------- provisioning troubleshooting ---------- */\nfunction initProvisionTrouble(){\n  const btns = document.querySelectorAll('#prov-case-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('prov-panel');\n  const cases = {\n    stuck: {sym:'Instance has been in PROVISIONING state for 20+ minutes.', fix:'Usually a capacity issue in that AD/shape combination \u2014 try a different Availability Domain or a similar shape, or check the OCI status page for regional issues.'},\n    cloudinitfail: {sym:'Instance is RUNNING but the application never came up; SSH works.', fix:'Check /var/log/cloud-init-output.log on the instance \u2014 a syntax error or failed package install in your cloud-init script silently stops the rest of the script.'},\n    bootvol: {sym:'Instance fails to boot; console shows a boot volume error.', fix:'Verify the boot volume wasn\\'t detached or its performance tier misconfigured; check the boot volume\\'s attachment status in the Console.'},\n    wrongimage: {sym:'Instance boots, but SSH key / OS tools don\\'t match what you expected.', fix:'Confirm the image OCID used at launch \u2014 a stale custom image or a similarly-named marketplace image is a common mix-up.'}\n  };\n  function render(key){ const c = cases[key]; panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.sym}</p><p class=\"small mt-lg\" style=\"color:var(--green);\">\u2713 ${c.fix}</p>`; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.provcase); }));\n  render('stuck');\n}\n\n;\n\n/* ---------- object storage ---------- */\nfunction initObjectStorage(){\n  const btn = document.getElementById('bkt-create'); if(!btn) return;\n  let buckets = [];\n  const list = document.getElementById('bkt-list');\n  function render(){\n    list.innerHTML = buckets.map((b,i)=>`\n      <div class=\"panel\" style=\"margin-top:12px;\">\n        <div class=\"console-toolbar\"><strong>${b.name}</strong> <span class=\"small\">(${b.tier})</span>\n          <input class=\"mini-input\" placeholder=\"object name\" id=\"obj-input-${i}\" style=\"flex:1;\">\n          <button class=\"chip-btn active\" data-upload=\"${i}\">Upload</button>\n        </div>\n        <div id=\"obj-list-${i}\">${b.objects.map(o=>`<div class=\"bucket-obj-row\"><span>\ud83d\udcc4 ${o}</span><span class=\"small\">uploaded</span></div>`).join('') || '<p class=\"small\">No objects yet.</p>'}</div>\n      </div>`).join('');\n  }\n  btn.addEventListener('click', ()=>{\n    const name = document.getElementById('bkt-name').value.trim(); if(!name) return;\n    const tier = document.getElementById('bkt-tier').value;\n    buckets.push({name, tier, objects:[]});\n    document.getElementById('bkt-name').value=''; render();\n  });\n  list.addEventListener('click', e=>{\n    if(e.target.dataset.upload!==undefined){\n      const i = e.target.dataset.upload; const inp = document.getElementById('obj-input-'+i);\n      const val = inp.value.trim(); if(!val) return;\n      buckets[i].objects.push(val); render();\n    }\n  });\n}\n\n/* ---------- block storage ---------- */\nfunction initBlockStorage(){\n  const btn = document.getElementById('bv-create'); if(!btn) return;\n  let vols = [];\n  const list = document.getElementById('bv-list');\n  function render(){\n    list.innerHTML = vols.map((v,i)=>`\n      <div class=\"vol-card\"><span><strong>${v.name}</strong> \u2014 ${v.size} GB \u2014 ${v.attached?'Attached to web-vm-01':'Unattached'}</span>\n        <span style=\"display:flex; gap:6px;\">\n          <button class=\"chip-btn\" data-attach=\"${i}\">${v.attached?'Detach':'Attach'}</button>\n          <button class=\"chip-btn\" data-backup=\"${i}\">Backup</button>\n          <button class=\"chip-btn\" data-clone=\"${i}\">Clone</button>\n          <button class=\"chip-btn\" data-resize=\"${i}\">Resize +50GB</button>\n        </span></div>`).join('');\n  }\n  btn.addEventListener('click', ()=>{ vols.push({name:'vol-'+(vols.length+1), size:100, attached:false}); render(); });\n  list.addEventListener('click', e=>{\n    const i = e.target.dataset.attach ?? e.target.dataset.backup ?? e.target.dataset.clone ?? e.target.dataset.resize;\n    if(i===undefined) return;\n    if(e.target.dataset.attach!==undefined) vols[i].attached = !vols[i].attached;\n    if(e.target.dataset.backup!==undefined){ /* simulated backup taken, no state change needed */ }\n    if(e.target.dataset.clone!==undefined) vols.push({name:vols[i].name+'-clone', size:vols[i].size, attached:false});\n    if(e.target.dataset.resize!==undefined) vols[i].size += 50;\n    render();\n  });\n  render();\n}\n\n/* ---------- file storage ---------- */\nfunction initFileStorage(){\n  const btn = document.getElementById('nfs-mount'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    document.getElementById('nfs-result').innerHTML = '\u2713 Mounted. <span class=\"mono\">df -h</span> now shows <span class=\"mono\">10.0.1.8:/shared-data  1.0T   12G  988G   1% /mnt/shared</span>';\n  });\n}\n\n/* ---------- storage design & cost ---------- */\nfunction initStorageDesign(){\n  const btns = document.querySelectorAll('#storage-workload-btns .chip-btn'); if(!btns.length) return;\n  const reco = document.getElementById('storage-reco');\n  const info = {\n    db: '\u2192 <strong>Block Storage</strong> \u2014 databases need low-latency, high-IOPS attached volumes with consistent performance, not shared/HTTP storage.',\n    backup: '\u2192 <strong>Object Storage (Archive tier)</strong> for anything older than ~30-90 days \u2014 infrequently accessed, long retention, lowest cost per GB.',\n    shared: '\u2192 <strong>File Storage (NFS)</strong> \u2014 multiple instances need concurrent read/write access to the same filesystem.',\n    media: '\u2192 <strong>Object Storage (Standard tier)</strong> \u2014 HTTP-native, scales infinitely, ideal for user-generated content served directly or via CDN.'\n  };\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); reco.innerHTML = info[b.dataset.sw]; }));\n  reco.innerHTML = info.db;\n\n  const chips = document.querySelectorAll('#tier-chips .tier-chip');\n  const costs = { standard: 25.60, ia: 10.20, archive: 2.60 };\n  chips.forEach(c=> c.addEventListener('click', ()=>{\n    chips.forEach(x=>x.classList.remove('active')); c.classList.add('active');\n    document.getElementById('tier-cost').textContent = '$'+costs[c.dataset.tier].toFixed(2);\n  }));\n}\n\n/* ---------- ansible ---------- */\nfunction initAnsible(){\n  const btn = document.getElementById('ansible-run'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const src = document.getElementById('ansible-editor').value;\n    const out = document.getElementById('ansible-out');\n    const taskNames = [...src.matchAll(/name:\\s*(.+)/g)].map(m=>m[1]).filter(n=>!n.includes('Configure'));\n    let lines = ['PLAY [Configure web servers] ***********************************', '', 'TASK [Gathering Facts] *****************************************', 'ok: [web-vm-01]', ''];\n    taskNames.forEach(t=>{ lines.push(`TASK [${t}] ` + '*'.repeat(Math.max(2,60-t.length))); lines.push(`changed: [web-vm-01]`); lines.push(''); });\n    lines.push('PLAY RECAP ******************************************************');\n    lines.push(`web-vm-01                  : ok=${taskNames.length+1}    changed=${taskNames.length}    unreachable=0    failed=0`);\n    out.textContent = '';\n    lines.forEach((l,i)=> setTimeout(()=>{ out.textContent += l+'\\n'; out.scrollTop = out.scrollHeight; }, i*180));\n  });\n}\n\n;\n\n/* ---------- console simulator 5 ---------- */\nfunction initConsoleSim5(){\n  const nav = document.querySelectorAll('.console-nav div[data-panel5]'); if(!nav.length) return;\n  nav.forEach(item=>{\n    item.addEventListener('click', ()=>{\n      nav.forEach(n=>n.classList.remove('active')); item.classList.add('active');\n      document.querySelectorAll('.console-panel5').forEach(p=>p.style.display='none');\n      document.getElementById('panel5-'+item.dataset.panel5).style.display='';\n    });\n  });\n}\n\n/* ---------- topology map ---------- */\nfunction initTopology(){\n  const nodes = document.querySelectorAll('#topology-svg .topo-node'); if(!nodes.length) return;\n  const detail = document.getElementById('topo-detail');\n  const info = {\n    igw: 'Internet Gateway \u2014 provides public inbound/outbound routing for the public subnet.',\n    'public-subnet': 'Public Subnet (10.0.1.0/24) \u2014 instances here can have public IPs.',\n    nat: 'NAT Gateway \u2014 gives the private subnet outbound-only internet access.',\n    'private-subnet': 'Private Subnet (10.0.2.0/24) \u2014 no public IPs, no inbound internet.',\n    sgw: 'Service Gateway \u2014 private route to OCI public services like Object Storage.'\n  };\n  nodes.forEach(n=> n.addEventListener('click', ()=> detail.textContent = info[n.dataset.t]));\n}\n\n/* ---------- CLI terminal 5 ---------- */\nfunction initTerminal5(){\n  const out = document.getElementById('term-out5'); const input = document.getElementById('term-input5'); if(!input) return;\n  const responses = {\n    'help': `Available commands:\n  oci network vcn create\n  oci network subnet create\n  oci network route-table create\n  oci network security-list list\n  oci compute instance launch\n  oci compute instance list\n  oci bv volume create\n  oci os bucket create\n  oci fs file-system create\n  clear`,\n    'oci network vcn create': `{ \"data\": {\"display-name\": \"prod-vcn\", \"cidr-block\": \"10.0.0.0/16\", \"lifecycle-state\": \"AVAILABLE\"} }`,\n    'oci network subnet create': `{ \"data\": {\"display-name\": \"public-web-subnet\", \"cidr-block\": \"10.0.1.0/24\"} }`,\n    'oci network route-table create': `{ \"data\": {\"display-name\": \"rt-public\", \"route-rules\": [{\"destination\": \"0.0.0.0/0\", \"network-entity-id\": \"igw-ocid\"}]} }`,\n    'oci network security-list list': `{ \"data\": [{\"display-name\": \"default-security-list\"}] }`,\n    'oci compute instance launch': `{ \"data\": {\"display-name\": \"web-vm-01\", \"lifecycle-state\": \"PROVISIONING\"} }`,\n    'oci compute instance list': `{ \"data\": [{\"display-name\": \"web-vm-01\", \"lifecycle-state\": \"RUNNING\"}] }`,\n    'oci bv volume create': `{ \"data\": {\"display-name\": \"vol-01\", \"size-in-gbs\": 100, \"lifecycle-state\": \"AVAILABLE\"} }`,\n    'oci os bucket create': `{ \"data\": {\"name\": \"app-backups\", \"storage-tier\": \"Standard\"} }`,\n    'oci fs file-system create': `{ \"data\": {\"display-name\": \"shared-fs\", \"lifecycle-state\": \"AVAILABLE\"} }`\n  };\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  function print(cmd, text, isErr){\n    const line = document.createElement('div');\n    line.innerHTML = `<div class=\"cmdline\">${esc(cmd)}</div><div style=\"color:${isErr?'#ff8a7a':'#c9f7d8'}; margin:4px 0 12px; white-space:pre-wrap;\">${esc(text)}</div>`;\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n  }\n  print('help', 'Welcome to the OCI CLI simulator. Type \"help\" for the supported command list.');\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const cmd = input.value.trim(); input.value=''; if(!cmd) return;\n    if(cmd==='clear'){ out.innerHTML=''; return; }\n    if(responses[cmd]){ print(cmd, responses[cmd]); return; }\n    print(cmd, 'Command not recognized in this simulator. Type \"help\" for the supported list.', true);\n  });\n}\n\n/* ---------- architecture labs checklist ---------- */\nfunction initLabs(){\n  const wrap = document.getElementById('labs-list'); if(!wrap) return;\n  const labs = [\n    ['Create VCN','Use the VCN Builder to define a 10.0.0.0/16 VCN.'],\n    ['Create Public Subnet','Add a public subnet within the VCN CIDR.'],\n    ['Create Private Subnet','Add a private subnet within the VCN CIDR.'],\n    ['Attach Internet Gateway','Attach an IGW so the public subnet can reach the internet.'],\n    ['Configure NAT Gateway','Attach a NAT Gateway for private subnet outbound access.'],\n    ['Configure Service Gateway','Attach an SGW for private access to OCI services.'],\n    ['Configure Route Tables','Add a route rule and test longest-prefix-match.'],\n    ['Configure Security Lists','Add an ingress rule and test a port.'],\n    ['Launch Compute','Run the Instance Launch Wizard end to end.'],\n    ['Cloud-init Automation','Run a cloud-init script during boot.'],\n    ['Attach Block Volume','Create and attach a block volume.'],\n    ['Create Object Storage Bucket','Create a bucket and upload an object.'],\n  ];\n  wrap.innerHTML = labs.map(([t,d],i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div><div class=\"lab-title\">Lab ${i+1}: ${t}</div><div class=\"lab-desc\">${d}</div></div></div>`).join('');\n  function updateProgress(){ document.getElementById('labs-progress').textContent = `${state.labsDone.size} / ${labs.length} labs complete`; }\n  wrap.querySelectorAll('.lab-item').forEach(item=>{\n    item.addEventListener('click', ()=>{\n      const i = item.dataset.i;\n      if(state.labsDone.has(i)){ state.labsDone.delete(i); item.classList.remove('done'); }\n      else { state.labsDone.add(i); item.classList.add('done'); }\n      updateProgress(); updateBadge5();\n    });\n  });\n  updateProgress();\n}\n\n/* ---------- troubleshooting lab 5 ---------- */\nfunction initTroubleshoot5(){\n  const btns = document.querySelectorAll('#ts5-case-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('ts5-panel');\n  const cases = {\n    sshfail: {err:'ssh: connect to host 140.238.10.5 port 22: Connection timed out', hint:'Check the security list/NSG for port 22 ingress, and confirm the instance has a public IP.', fix:'Fix: add an ingress rule allowing TCP/22 from your IP in the Security List or NSG attached to the subnet/VNIC.'},\n    nointernet: {err:'curl: (7) Failed to connect to google.com port 443: Connection timed out', hint:'Which subnet is this instance in \u2014 public or private?', fix:'Fix: if private, attach/verify a NAT Gateway and a matching route rule for 0.0.0.0/0.'},\n    wrongroute: {err:'Traffic to 172.16.0.0/16 is being routed via the Internet Gateway instead of the DRG.', hint:'Check for a more specific (or incorrectly ordered) route rule.', fix:'Fix: add a route rule for 172.16.0.0/16 \u2192 DRG; it will win over a broader 0.0.0.0/0 rule via longest-prefix-match.'},\n    slblock: {err:'Connection to db-host:5432 refused by the network.', hint:'Security Lists are stateful but each direction still needs an explicit rule.', fix:'Fix: add an ingress rule for TCP/5432 from the app subnet\\'s CIDR on the database subnet\\'s Security List.'},\n    nsgblock: {err:'Instance in an NSG-protected subnet can\\'t reach an app on port 8080, even though the Security List allows it.', hint:'Both Security Lists AND NSGs must allow the traffic \u2014 it\\'s the union check, not either/or.', fix:'Fix: add a matching ingress rule to the NSG attached to that VNIC.'},\n    cifail: {err:'Application never started after launch; SSH access works fine.', hint:'Check /var/log/cloud-init-output.log for errors in your script.', fix:'Fix: a bad package name or malformed YAML in cloud-init silently halts the rest of the script \u2014 fix the syntax and relaunch.'},\n    bvfail: {err:'Instance shows lifecycle state FAILED shortly after launch.', hint:'Check the boot volume\\'s own lifecycle state in the Console.', fix:'Fix: the boot volume may have failed to provision (capacity/backend issue) \u2014 terminate and relaunch, or open a support request if it recurs.'},\n    ospermission: {err:'PUT to bucket returns 403 Forbidden.', hint:'Check the IAM policy for \"manage objects\" on this bucket\\'s compartment.', fix:'Fix: grant the calling principal at least \"use object-family\" (or \"manage\" for writes/deletes) in the correct compartment.'},\n    mountfail: {err:'mount.nfs: Connection timed out', hint:'Check the mount target\\'s NSG/Security List for NFS ports (2048-2050, 111).', fix:'Fix: allow TCP/UDP 2048-2050 and 111 from the client subnet on the mount target\\'s NSG or Security List.'}\n  };\n  function render(key){\n    const c = cases[key];\n    panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.err}</p>\n      <button class=\"chip-btn active mt-lg\" id=\"ts5-hint-btn\">Show hint</button>\n      <p class=\"small mt-lg\" id=\"ts5-hint\" style=\"display:none;\">${c.hint}</p>\n      <button class=\"chip-btn mt-lg\" id=\"ts5-fix-btn\" style=\"display:none;\">Reveal fix</button>\n      <p class=\"small mt-lg\" id=\"ts5-fix\" style=\"display:none; color:var(--green);\">${c.fix}</p>`;\n    document.getElementById('ts5-hint-btn').addEventListener('click', function(){ document.getElementById('ts5-hint').style.display='block'; document.getElementById('ts5-fix-btn').style.display='inline-flex'; this.disabled=true; });\n    document.getElementById('ts5-fix-btn').addEventListener('click', function(){ document.getElementById('ts5-fix').style.display='block'; this.disabled=true; });\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.case5); }));\n  render('sshfail');\n}\n\n;\n\n/* ---------- flashcards 5 ---------- */\nfunction initFlashcards5(){\n  const wrap = document.getElementById('flash-wrap5'); if(!wrap) return;\n  const cards = [\n    ['VCN CIDR range','Must be between /16 and /30'],\n    ['Longest Prefix Match','The most specific matching route rule wins'],\n    ['Internet Gateway','Public inbound + outbound internet traffic'],\n    ['NAT Gateway','Private subnet outbound-only internet access'],\n    ['Service Gateway','Private access to OCI public services, no internet'],\n    ['Security List','Stateful, applies to an entire subnet'],\n    ['NSG','Stateful, applies to specific VNICs \u2014 finer-grained'],\n    ['cloud-init','Runs once on first boot to configure the instance'],\n    ['Object vs Block vs File','HTTP/unstructured vs attached volumes vs shared NFS'],\n    ['Local Peering Gateway','Connects two VCNs in the same region'],\n    ['Terraform vs Ansible','Terraform provisions infra; Ansible configures software'],\n    ['Instance Metadata endpoint','http://169.254.169.254/latest/meta-data/'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- certification quiz 5 ---------- */\nfunction initQuiz5(){\n  const wrap = document.getElementById('quiz-wrap5'); if(!wrap) return;\n  const Q = [\n    {q:'What is the valid CIDR prefix range for an OCI VCN?', o:['/8 to /24','/16 to /30','/24 to /32','/1 to /16'], c:1, e:'OCI requires VCN CIDR blocks between /16 and /30.'},\n    {q:'A /24 subnet in OCI has how many usable host addresses (accounting for OCI-reserved addresses)?', o:['256','254','251','128'], c:2, e:'254 usable minus OCI\\'s reserved addresses (network, broadcast, and a few reserved for OCI networking) leaves 251 usable.'},\n    {q:'Two route rules match a destination: 10.0.0.0/8 and 10.0.1.0/24. Which wins?', o:['10.0.0.0/8, because it was added first','10.0.1.0/24, the more specific match','Both are applied simultaneously','Neither \u2014 a conflict error occurs'], c:1, e:'Longest-prefix-match means the more specific (longer prefix) rule always wins.'},\n    {q:'Which gateway allows a private subnet outbound-only internet access?', o:['Internet Gateway','NAT Gateway','Service Gateway','Local Peering Gateway'], c:1, e:'NAT Gateway is specifically for outbound-only access from private subnets.'},\n    {q:'Which gateway lets a private subnet reach Object Storage without using the internet?', o:['NAT Gateway','Internet Gateway','Service Gateway','Dynamic Routing Gateway'], c:2, e:'Service Gateway provides private access to OCI public services like Object Storage.'},\n    {q:'A public subnet instance still can\\'t be reached from the internet. IGW is attached. What else must be checked?', o:['The instance\\'s hostname','Route table pointing to the IGW, and Security List/NSG allowing the traffic','The compartment name','The tenancy OCID'], c:1, e:'An attached IGW alone isn\\'t enough \u2014 the route table must route 0.0.0.0/0 to it, and security rules must allow the traffic.'},\n    {q:'What is the key difference between Security Lists and NSGs?', o:['NSGs are stateless, Security Lists are stateful','Security Lists apply per-VNIC, NSGs apply per-subnet','Security Lists apply to the whole subnet, NSGs apply to specific VNICs','They are functionally identical'], c:2, e:'Security Lists are subnet-wide; NSGs let you scope rules to individual VNICs.'},\n    {q:'Two VCNs in the same region need private connectivity. What should you use?', o:['NAT Gateway','Local Peering Gateway','Internet Gateway','Object Storage'], c:1, e:'Local Peering Gateway (LPG) connects two VCNs in the same region privately.'},\n    {q:'cloud-init runs:', o:['On every boot','Only on the very first boot','Only when manually triggered','Every time SSH is used'], c:1, e:'cloud-init executes its configuration once, on the instance\\'s first boot.'},\n    {q:'Which OCI storage type is best for a shared filesystem mounted by 10 web servers simultaneously?', o:['Block Storage','Object Storage','File Storage (NFS)','Archive Storage'], c:2, e:'File Storage provides an NFS-shared filesystem mountable by multiple instances concurrently.'},\n    {q:'Which storage tier is cheapest but has retrieval times measured in hours?', o:['Standard','Infrequent Access','Archive','Block'], c:2, e:'Archive Storage is the lowest-cost tier, trading off slow (hours-long) retrieval.'},\n    {q:'What does Terraform primarily do, versus Ansible?', o:['Terraform configures software; Ansible provisions infrastructure','Terraform provisions infrastructure; Ansible configures software on top of it','They do exactly the same thing','Terraform only works with OCI'], c:1, e:'Terraform is for provisioning infra (declarative, stateful); Ansible configures what runs on top (procedural, agentless).'},\n    {q:'An instance is stuck in PROVISIONING for a long time. What\\'s a likely cause?', o:['DNS misconfiguration','Capacity constraints for that shape/AD combination','A missing security list rule','An expired SSH key'], c:1, e:'Provisioning delays are commonly capacity-related for the chosen shape in that Availability Domain.'},\n    {q:'A cloud-init script silently fails partway through. Where do you look first?', o:['/var/log/messages only','/var/log/cloud-init-output.log','The Security List','The route table'], c:1, e:'/var/log/cloud-init-output.log captures cloud-init\\'s execution and errors.'},\n    {q:'Which endpoint do you query from inside an instance to get instance metadata?', o:['http://metadata.oraclecloud.com','http://169.254.169.254/latest/meta-data/','https://iam.oraclecloud.com/metadata','http://localhost/meta'], c:1, e:'169.254.169.254 is the standard instance metadata service endpoint.'},\n    {q:'A private-subnet instance can reach Object Storage but not the public internet. This is consistent with:', o:['A misconfigured Service Gateway only','A working Service Gateway but no NAT Gateway configured','A missing Security List entirely','An expired SSH key'], c:1, e:'Service Gateway handles OCI service traffic; general internet access still requires a NAT Gateway for a private subnet.'},\n    {q:'You need port 8080 open only for 3 specific \"api\" instances, not the whole subnet. What\\'s the right tool?', o:['Security List','NSG','Internet Gateway','Route Table'], c:1, e:'NSGs scope rules to specific VNICs/instances rather than the entire subnet.'},\n    {q:'Which volume type provides raw block-level storage for a compute instance\\'s OS?', o:['Object Storage bucket','Boot Volume (Block Storage)','File Storage export','Archive container'], c:1, e:'The Boot Volume is Block Storage that holds the instance\\'s operating system.'},\n    {q:'What validation should an IP/subnet planner perform when adding a new subnet CIDR?', o:['Check it\\'s in alphabetical order','Check for overlapping ranges with existing subnets and containment within the VCN CIDR','Check the subnet name length','Check the AD count'], c:1, e:'Overlap detection and containment within the parent VCN CIDR are the two critical validations.'},\n    {q:'A route rule for 0.0.0.0/0 points to an Internet Gateway in a subnet meant to be private. What\\'s the risk?', o:['No risk, it\\'s just a formality','Instances there may unexpectedly gain internet routing if they also get public IPs','It automatically encrypts traffic','It disables NSGs'], c:1, e:'A stray default route to an IGW undermines the \"private\" design intent if any instance there is later assigned a public IP.'},\n  ];\n  state.quizTotal = Q.length;\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz5-${qi}\">\n      <div class=\"qtext\">${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q5-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n      state.quizAnswered++; if(chosen===Q[qi].c) state.quizScore++;\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score5').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display5').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge5();\n    });\n  });\n}\n\n/* ---------- badge / certificate 5 ---------- */\nfunction updateBadge5(){\n  const scrollPct = window.__lastScrollPct5 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle5'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct5').textContent = combined+'%';\n  const title = document.getElementById('badge-title5'); const sub = document.getElementById('badge-sub5');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Day 5 Complete'; sub.textContent='Certificate preview unlocked below.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the quiz.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the quiz to preview your certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display5').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n}\n"};
